export const MANUAL_CHECKPOINTS: ManualCheckpoint[] = [
  {"id":"SW-001","tab":"Sitewide & Header","section":"Announcement bar","checkpoint":"An announcement (notice) bar sits above the header on every page","why":"It is the first thing every visitor reads; it carries the one message that removes the biggest hesitation (shipping cost, offer, delivery time).","how":"Open the homepage, a collection page and a product page on desktop and phone. Look at the very top strip above the logo.","pass":"A thin bar is visible on all page types, on both devices, without scrolling.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Website Auditing Sheet - Product Page (row 2)","importance":"Medium"},
  {"id":"SW-002","tab":"Sitewide & Header","section":"Announcement bar","checkpoint":"The bar states a concrete, current reason to buy (free-shipping threshold, active sale, delivery promise, guarantee)","why":"Vague slogans ('Welcome to our store') waste the most-read line on the site.","how":"Read the bar text. Ask: does it give a number or a promise a shopper can act on?","pass":"e.g. 'Free delivery on orders over 800 EGP' or '2–4 day delivery across Egypt'. Numbers match checkout.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"SW-003","tab":"Sitewide & Header","section":"Announcement bar","checkpoint":"If the bar rotates several messages, each stays long enough to read (≥4 s) and none is outdated","why":"Fast or expired rotating messages (finished sales, old dates) look careless and break trust.","how":"Watch the bar for 20 seconds. Note every message and check dates/offers are still valid.","pass":"All messages are current; rotation is slow enough to read a full sentence.","ref":"","importance":"Low"},
  {"id":"SW-004","tab":"Sitewide & Header","section":"Announcement bar","checkpoint":"The free-shipping threshold shown in the bar is the same amount used in the cart and checkout","why":"A mismatch between promise and checkout is one of the fastest ways to lose a buyer at the last step.","how":"Note the amount in the bar. Add products just under and just over it, then compare what cart and checkout charge.","pass":"Same threshold everywhere; checkout applies it correctly.","ref":"","importance":"High"},
  {"id":"SW-005","tab":"Sitewide & Header","section":"Header","checkpoint":"The logo is visible top-left (top-right on Arabic/RTL sites) and links back to the homepage","why":"Visitors expect the logo to be the 'home' button; when it isn't, they get lost.","how":"Click the logo from a product page on desktop and phone.","pass":"Returns to the homepage on both devices.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf","importance":"Low"},
  {"id":"SW-006","tab":"Sitewide & Header","section":"Header","checkpoint":"Main navigation has 5 links or fewer at the top level","why":"Too many choices slow people down (choice overload); clear top-level categories help them find products faster.","how":"Count the links in the main menu bar on desktop (do not count dropdown children).","pass":"≤5 top-level items, each a clear shopping category or key page (e.g. Shop, Best sellers, Bundles, About, Contact).","ref":"Website Auditing Sheet - Product Page (row 1: 'Limit Navigational links to a max of 5')","importance":"Medium"},
  {"id":"SW-007","tab":"Sitewide & Header","section":"Header","checkpoint":"Menu labels use the words customers use (product types / problems solved), not internal or brand jargon","why":"Shoppers scan for familiar words; clever names they don't understand get skipped.","how":"Read every menu label. For each, ask: would a first-time visitor know what is inside?","pass":"Plain labels like 'Hair oils', 'Skin care', 'Gift sets'.","ref":"","importance":"Medium"},
  {"id":"SW-008","tab":"Sitewide & Header","section":"Header","checkpoint":"Dropdown / mega-menu opens reliably, does not close while the mouse moves to it, and every link works","why":"Broken or 'jumpy' menus block navigation completely for some visitors.","how":"Hover each top-level item on desktop and move the mouse slowly into the dropdown; click 3 random links.","pass":"Menus stay open while moving into them; all tested links load the right page.","ref":"","importance":"High"},
  {"id":"SW-009","tab":"Sitewide & Header","section":"Header","checkpoint":"Search is visible (icon or bar) in the header on desktop and phone","why":"Visitors who search usually convert far better than browsers; hiding search costs high-intent sales.","how":"Look for a search icon or box in the header on both devices without opening the menu.","pass":"Search icon/box visible in the header on both devices.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf","importance":"Medium"},
  {"id":"SW-010","tab":"Sitewide & Header","section":"Header","checkpoint":"Cart icon is visible at all times, shows the item count, and opens the cart drawer or cart page","why":"People check the cart constantly; a missing count makes them unsure the add-to-cart worked.","how":"Add one product, then look at the cart icon on desktop and phone; click it.","pass":"Count badge updates instantly; clicking opens the cart.","ref":"","importance":"High"},
  {"id":"SW-011","tab":"Sitewide & Header","section":"Header","checkpoint":"Account / login icon is present but not more prominent than the cart","why":"Login is secondary for most shoppers; it should not compete with buying.","how":"Look at the header icon order and size.","pass":"Account icon small, after search and before/next to cart.","ref":"","importance":"Low"},
  {"id":"SW-012","tab":"Sitewide & Header","section":"Header","checkpoint":"The header becomes sticky (stays on screen) when scrolling, or a sticky buy bar replaces it on product pages","why":"Keeps navigation, search and cart one tap away on long pages.","how":"Scroll down a long page on desktop and phone. Does the header (or a sticky bar) stay?","pass":"Header or compact sticky bar stays visible without covering content.","ref":"","importance":"Low"},
  {"id":"SW-013","tab":"Sitewide & Header","section":"Header","checkpoint":"Language and currency switchers (if the store sells to several countries) are easy to find and work","why":"A visitor who sees the wrong currency or language often leaves before asking.","how":"Find the switcher, change it, and check prices and page text update correctly.","pass":"Switch works; prices convert; layout is not broken in the second language.","ref":"","importance":"Medium"},
  {"id":"SW-014","tab":"Sitewide & Header","section":"Footer","checkpoint":"The footer contains: contact details (phone/WhatsApp/email), shipping, returns, privacy and terms links","why":"Shoppers scroll to the footer to check the store is real and safe before buying.","how":"Scroll to the footer on desktop and phone and list what is there.","pass":"All five items present, all links load a real page (not empty templates).","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf","importance":"Medium"},
  {"id":"SW-015","tab":"Sitewide & Header","section":"Footer","checkpoint":"Payment method icons and a security/trust message appear in the footer","why":"Confirms the store accepts the shopper's preferred payment before they reach checkout.","how":"Look for card / wallet / COD / BNPL icons in the footer.","pass":"Icons match the methods actually available at checkout.","ref":"","importance":"Low"},
  {"id":"SW-016","tab":"Sitewide & Header","section":"Footer","checkpoint":"Social media links point to the brand's real, active accounts","why":"Active social accounts are proof the brand is real; dead or wrong links do the opposite.","how":"Click every social icon. Check the account is the brand's and posted recently.","pass":"All links open the brand's own, active profiles.","ref":"","importance":"Low"},
  {"id":"SW-017","tab":"Sitewide & Header","section":"Footer","checkpoint":"No leftover template content anywhere (placeholder text, demo addresses, 'Lorem ipsum', theme-demo links, fake testimonials)","why":"Template leftovers instantly make a store look fake. This was found live on a past client audit.","how":"Scan footer, About and Contact pages for placeholder emails/phones/addresses and demo names; check links don't point to a theme demo site.","pass":"Zero placeholder or demo content.","ref":"Optimizers past audit (Inventel, 2026-10-26)","importance":"Critical"},
  {"id":"SW-018","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Every page loads without visible errors, blank gaps, broken images or overlapping elements","why":"A page that 'looks broken' makes visitors leave silently — they never report it.","how":"Scroll every audited page slowly top to bottom on desktop and phone; note any empty white blocks, broken images, overlaps.","pass":"No broken or empty areas on any audited page.","ref":"Optimizers past audit (Balqees, 2026-08-16)","importance":"Critical"},
  {"id":"SW-019","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Pop-ups (newsletter, discount, exit-intent) do not appear in the first seconds and are easy to close","why":"An instant pop-up covering the product is one of the most hated experiences and raises bounce rate.","how":"Open the homepage and a product page in a private window; note when pop-ups appear and how to close them on phone.","pass":"Pop-up appears after engagement (time/scroll/exit), has a visible close (X), and does not block the add-to-cart button on mobile.","ref":"","importance":"High"},
  {"id":"SW-020","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Chat / WhatsApp bubble never covers the add-to-cart, checkout or quantity buttons on mobile","why":"A floating bubble on top of the buy button causes mis-taps exactly at the moment of purchase.","how":"On a phone, scroll the product page, cart drawer and cart page; watch where the bubble sits relative to buttons.","pass":"Bubble never overlaps a buying control.","ref":"Optimizers past audit (Balqees mobile check)","importance":"High"},
  {"id":"SW-021","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Cookie / consent banner (where needed) is small, does not cover the main CTA, and both Accept and Decline work","why":"A huge banner hides the offer; a broken one creates legal risk.","how":"Open the site in a private window (with an EU VPN for EU traffic); test both buttons.","pass":"Banner is compact, both choices work, choice is remembered.","ref":"","importance":"Medium"},
  {"id":"SW-022","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Brand colours, fonts and button styles are consistent across all pages","why":"Inconsistency feels unprofessional and makes the main button harder to recognise.","how":"Compare the primary button and headings on homepage, collection, product and cart.","pass":"One primary button style used for buying actions everywhere.","ref":"","importance":"Low"},
  {"id":"SW-023","tab":"Sitewide & Header","section":"Global UX","checkpoint":"The primary call-to-action colour is used only for buying actions and stands out from everything else","why":"If many elements share the CTA colour, the eye cannot find the button that matters.","how":"Squint at each page (or blur a screenshot): is the buy button still the most visible element?","pass":"Add-to-cart / checkout is the most visually dominant element above the fold.","ref":"Audit wireframes & workflows folder → 02-Page Layouts Presentation.pdf","importance":"High"},
  {"id":"SW-024","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Text is readable: body text ≥16px on mobile, good contrast with the background, short paragraphs","why":"Hard-to-read text is skipped, so benefits and trust messages are never seen.","how":"On a phone, read a product description and a policy page; check small grey text on light backgrounds.","pass":"Comfortable to read without zooming; no light-grey-on-white body text.","ref":"","importance":"Medium"},
  {"id":"SW-025","tab":"Sitewide & Header","section":"Global UX","checkpoint":"All buttons and links look clickable and have a clear hover/tap state","why":"Visitors don't click what doesn't look like a button.","how":"Hover buttons on desktop; tap on phone; check text links are underlined or clearly styled.","pass":"Every interactive element is obviously interactive.","ref":"","importance":"Low"},
  {"id":"SW-026","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Custom 404 page exists and helps the visitor continue (search, best sellers, home link)","why":"Broken links from ads or old posts otherwise end the visit.","how":"Visit yoursite.com/this-page-does-not-exist.","pass":"Branded 404 with search and product links.","ref":"","importance":"Low"},
  {"id":"SW-027","tab":"Sitewide & Header","section":"Global UX","checkpoint":"Arabic / RTL layout (if used) mirrors correctly: text right-aligned, arrows and steppers in the right direction, no mixed-direction glitches","why":"Mirroring bugs (e.g. quantity + and − swapped) cause wrong orders and look broken.","how":"Check headers, carousels' arrows, quantity steppers, prices with currency, and form fields in Arabic.","pass":"Everything reads naturally right-to-left; numbers and currency display correctly.","ref":"Optimizers past audit (Balqees RTL stepper)","importance":"Medium"},
  {"id":"SW-028","tab":"Sitewide & Header","section":"Site search","checkpoint":"Search returns the right product for the product's exact name and for common misspellings / Arabic-English variants","why":"Searchers have high buying intent; a 'no results' page loses them.","how":"Search the exact name of a best seller, then a misspelling, then the Arabic/English alternative name.","pass":"The right product appears first in all three searches.","ref":"Optimizers past audit (Tharaa search test)","importance":"High"},
  {"id":"SW-029","tab":"Sitewide & Header","section":"Site search","checkpoint":"Search shows live suggestions with product images and prices while typing","why":"Instant results shorten the path to the product page.","how":"Type the first 3 letters of a product name.","pass":"Suggestions with image + price appear instantly.","ref":"","importance":"Medium"},
  {"id":"SW-030","tab":"Sitewide & Header","section":"Site search","checkpoint":"A 'no results' search shows helpful alternatives (best sellers, categories, contact)","why":"Dead-end pages end visits.","how":"Search for nonsense like 'zzqx'.","pass":"Page suggests products/categories instead of being empty.","ref":"","importance":"Low"},
  {"id":"SW-031","tab":"Sitewide & Header","section":"Policies & trust pages","checkpoint":"Shipping policy states costs, delivery times per region, and couriers in plain language","why":"Unknown delivery cost/time is a top reason people abandon carts.","how":"Open the shipping policy page and read it as a customer.","pass":"Clear table or list of cost and time per area.","ref":"","importance":"High"},
  {"id":"SW-032","tab":"Sitewide & Header","section":"Policies & trust pages","checkpoint":"Return / exchange policy is clear, fair and easy to find (linked near add-to-cart and in footer)","why":"A visible, simple return promise reduces the risk of buying.","how":"Open the returns policy; check the number of days, conditions and how to start a return.","pass":"Simple steps, a clear number of days, a contact method.","ref":"","importance":"High"},
  {"id":"SW-033","tab":"Sitewide & Header","section":"Policies & trust pages","checkpoint":"An About page tells the brand story with real people, photos and why the brand exists","why":"People buy from brands they believe are real and trustworthy.","how":"Open the About page.","pass":"Real founder/team photos and a specific story, not generic text.","ref":"","importance":"Medium"},
  {"id":"SW-034","tab":"Sitewide & Header","section":"Policies & trust pages","checkpoint":"Contact page offers at least two fast channels (WhatsApp/phone + email/form) and states response time","why":"Pre-purchase questions that go unanswered become lost sales.","how":"Open the Contact page; send a test message if allowed.","pass":"Two or more channels, response time promised, form works.","ref":"","importance":"Medium"},
  {"id":"HP-001","tab":"Homepage","section":"Header","checkpoint":"Main navigation has 5–6 links max, and weak links (e.g. Blog) are replaced with buying links (e.g. 'On sale')","why":"Sheet comment on the Home tab: 'Change the blog navigation to on sale items'.","how":"Count and read top-level menu links.","pass":"≤6 links, all leading to products/offers or key trust pages.","ref":"Website Auditing Sheet – Home Page tab (row 1)","importance":"Medium"},
  {"id":"HP-002","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"5-second test passed: a stranger can say what the store sells, for whom, and why it is better within 5 seconds","why":"You have 5–8 seconds to capture attention; if the offer is unclear the visitor leaves.","how":"Show the first screen (no scrolling) to someone who doesn't know the brand for 5 s, hide it, ask the 3 questions. Do it on phone and laptop.","pass":"They answer correctly without guessing.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.5 Attention); 5-Second Test tab; Website Auditing Sheet – Home Page tab (row 5)","importance":"Critical"},
  {"id":"HP-003","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"A star rating with a number and customer count sits directly ABOVE the hero headline (e.g. '★★★★★ Rated 4.8/5 by 20,000+ customers')","why":"Social proof before the promise makes the promise believable. Every homepage wireframe and every before/after example adds this line.","how":"Look at the line just above the main headline on both devices. Check the number matches the review app.","pass":"Rating + score + quantified customer count above the H1; numbers are real.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 3)","importance":"High"},
  {"id":"HP-004","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"The headline is a value proposition built on a benefit — not just the brand name, a sale or a 'new flavour' announcement","why":"Discount-only or launch headlines don't tell new visitors why the brand is worth it. The examples all replace sale headlines with benefit headlines.","how":"Read the H1. Ask: does it say what the customer GETS?","pass":"e.g. 'Supplements that show their work', 'Fuel your body. Power your performance.'","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 4)","importance":"High"},
  {"id":"HP-005","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"A subheadline explains who it is for and how it works / which problem it solves","why":"Turns a slogan into a concrete reason to stay.","how":"Read the line under the H1.","pass":"One or two lines naming the audience and outcome.","ref":"Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy); Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Medium"},
  {"id":"HP-006","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"3 check-mark benefit/proof bullets sit under the headline","why":"Scannable proof points answer 'why this?' faster than a paragraph.","how":"Count bullets in the hero.","pass":"Exactly ~3 short benefit bullets with check icons.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 6)","importance":"Medium"},
  {"id":"HP-007","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"ONE primary hero button: solid, high-contrast, large (not an outline/ghost button or small pill)","why":"Ghost and small pill buttons get far fewer clicks. Every 'after' example replaces them with a big solid button.","how":"Squint at the hero: is the button the most visible element after the headline?","pass":"One solid, full-width-on-mobile button.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 7)","importance":"High"},
  {"id":"HP-008","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"Hero button label is specific (e.g. 'Shop Bestsellers', 'Find my routine') rather than 'Shop now' / 'Shop all'","why":"Specific labels send people to the products most likely to convert and set expectations.","how":"Read the label and click it — where does it go?","pass":"Label says where it goes; lands on best sellers or the hero product.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 16)","importance":"Medium"},
  {"id":"HP-009","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"On mobile, headline + bullets + button are all visible in the first screen; a large image does not push them below the fold","why":"Most traffic is mobile; if the first screen is only a picture, the message is never read.","how":"Open on a 390×844 phone screen without scrolling.","pass":"Copy and CTA visible; image below or beside them.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 5)","importance":"High"},
  {"id":"HP-010","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"Text placed over a hero image is readable (dark overlay / contrast); no promotional text baked into the image","why":"Text inside images can't be read on phones, isn't translated and isn't seen by Google.","how":"Zoom out on a phone; try to read every word.","pass":"All text is real text with good contrast.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 8)","importance":"Medium"},
  {"id":"HP-011","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"Single-product brands: a clean packshot of the product sits next to the copy (desktop) or between headline and bullets (mobile)","why":"Visitors must see exactly what they are buying.","how":"Check the hero image.","pass":"Clear product image in the hero.","ref":"Audit wireframes & workflows folder → 17-Single product homepage - desktop.pdf; Audit wireframes & workflows folder → 17-Single product homepage - mobile.pdf","importance":"Medium"},
  {"id":"HP-012","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"Payment logos and/or 'Secure checkout' appear directly under (or above, on mobile) the main CTAs","why":"Reassures at the moment of clicking.","how":"Look around each hero/closing CTA.","pass":"Payment icons or secure line next to CTAs.","ref":"Audit wireframes & workflows folder → 17-Single product homepage - desktop.pdf; Audit wireframes & workflows folder → 01-Homepage - mobile.pdf","importance":"Low"},
  {"id":"HP-013","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"A short testimonial (photo, name, 'Verified buyer', stars, 1–2 lines) sits near the hero CTA","why":"A real person's words next to the button reduce doubt.","how":"Look under the hero CTA (especially on mobile).","pass":"Mini review with photo and name near the CTA.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Low"},
  {"id":"HP-014","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"Chat bubbles, discount teasers and pop-ups never cover the hero headline or button on mobile","why":"Two of the before/after examples were fixed specifically for this.","how":"Load the homepage fresh on a phone; wait 10 s.","pass":"Nothing floats over the hero text or CTA.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"High"},
  {"id":"HP-015","tab":"Homepage","section":"Hero (above the fold)","checkpoint":"If the hero is a slider/carousel, the first slide carries the main message and the slider does not auto-rotate too fast","why":"Visitors rarely see slides 2–5; fast rotation stops people reading.","how":"Watch the hero for 15 s.","pass":"Static hero, or first slide = main value proposition, ≥5 s per slide.","ref":"","importance":"Medium"},
  {"id":"HP-016","tab":"Homepage","section":"Trust & authority","checkpoint":"An 'As recommended by' / press or partner logo bar appears right after the hero (only real logos)","why":"Borrowed authority right after the promise. Fake or unlicensed logos are a legal and trust risk.","how":"Scroll just below the hero. Verify each logo is real (ask the client for proof).","pass":"Real press/partner/retailer logos.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy); Website Auditing Sheet - Product Page (row 13)","importance":"Medium"},
  {"id":"HP-017","tab":"Homepage","section":"Trust & authority","checkpoint":"A USP strip (shipping, returns, quality/reviews, support) sits under the header; on mobile it is a one-line rotating ticker","why":"Answers the 4 most common doubts before the visitor asks.","how":"Look under the header on both devices.","pass":"4 icon + text promises; ticker on mobile.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 2)","importance":"Medium"},
  {"id":"HP-018","tab":"Homepage","section":"Trust & authority","checkpoint":"The USPs include a guarantee (money-back, happiness guarantee) — only if the store really offers one","why":"Risk reversal is one of the strongest trust signals.","how":"Read the USP strip; compare with the refund policy.","pass":"Guarantee shown and matches the policy.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Medium"},
  {"id":"HP-019","tab":"Homepage","section":"Trust & authority","checkpoint":"A 3-step 'Transformation' / how-it-works section (order → delivered → result) with icons appears early on the page","why":"Shows how easy buying is and what life looks like after. It is the 'T' in ATIDFA.","how":"Look for a 3-step icon row after the press bar.","pass":"3 icons with short titles like 'Order today', 'Ships in 24h', 'See results in 2 weeks'.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → AIDA Framework by Oliver Kenyon.pdf (p.6); Website Auditing Sheet – Home Page tab (row 9)","importance":"Medium"},
  {"id":"HP-020","tab":"Homepage","section":"Trust & authority","checkpoint":"Benefit claims are backed by numbers, studies or certifications where possible","why":"Specific numbers ('83% reported…') are believed; vague claims are skipped.","how":"List the main claims on the page; look for proof next to each.","pass":"Key claims carry a number, source or badge.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Low"},
  {"id":"HP-021","tab":"Homepage","section":"Merchandising","checkpoint":"A 'Best sellers' grid sits high on the page (4 across desktop, 2×2 mobile) with image, rating, name and price on each card","why":"Most visitors want to see products quickly; best sellers convert best.","how":"Scroll to the first product grid.","pass":"Best sellers within the first 2–3 screens; complete card info.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy); Website Auditing Sheet – Home Page tab (row 10)","importance":"High"},
  {"id":"HP-022","tab":"Homepage","section":"Merchandising","checkpoint":"Product cards have a quick 'Add to cart' button (and it actually works)","why":"Saves a click; but a broken quick-add silently loses sales (found in a past audit).","how":"Click quick-add on 2 cards; check the cart count updates.","pass":"Product added, drawer opens or count updates.","ref":"Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy)","importance":"High"},
  {"id":"HP-023","tab":"Homepage","section":"Merchandising","checkpoint":"Cards use real badges ('New', 'Best seller', 'Low stock') sparingly","why":"Badges guide choice; too many cancel each other out.","how":"Look at the grid.","pass":"A few honest badges.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf","importance":"Low"},
  {"id":"HP-024","tab":"Homepage","section":"Merchandising","checkpoint":"Category tiles (about 3) with image, label and CTA link to the right collections; placed right under the hero when the catalogue is large","why":"Lets visitors self-route quickly.","how":"Click each category tile.","pass":"Correct collection opens each time.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Website Auditing Sheet – Home Page tab (row 13)","importance":"Medium"},
  {"id":"HP-025","tab":"Homepage","section":"Merchandising","checkpoint":"Categories are named the way customers think (by need or problem, e.g. 'Shop by health need') where relevant","why":"Problem-based naming helps visitors who don't know product names.","how":"Read the category names.","pass":"Customer language, not internal product-line names.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Low"},
  {"id":"HP-026","tab":"Homepage","section":"Merchandising","checkpoint":"Bundles / offers show an itemised value stack (what's included, crossed-out values, 'You save X')","why":"Makes the deal concrete and easy to compare.","how":"Find any bundle or kit promoted on the homepage.","pass":"Items listed with values, total value, price today, savings.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after)","importance":"Low"},
  {"id":"HP-027","tab":"Homepage","section":"Merchandising","checkpoint":"Customisation / personalisation options are highlighted on the homepage (if the store offers them)","why":"Visitors who don't know they can customise won't look for it. This was a reviewer comment on the original audit sheet.","how":"Ask the client which products are customisable; look for a mention on the homepage.","pass":"Clear section or banner explaining the customisation option.","ref":"Website Auditing Sheet - Product Page (additional comments)","importance":"Medium"},
  {"id":"HP-028","tab":"Homepage","section":"Persuasion & content","checkpoint":"Alternating image + text blocks each have an emotive headline, ~3 bullets, a CTA and a rating next to the CTA","why":"This is how the wireframe keeps persuading while always offering the next step.","how":"Scroll through the content blocks.","pass":"Each block ends with a CTA.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy)","importance":"Medium"},
  {"id":"HP-029","tab":"Homepage","section":"Persuasion & content","checkpoint":"Every major section ends with a CTA, so the visitor is never more than one scroll from a buy button","why":"People decide at different points on the page.","how":"Scroll slowly; count screens between CTAs.","pass":"No more than ~1.5 screens without a CTA.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → AIDA Framework by Oliver Kenyon.pdf (p.10)","importance":"Medium"},
  {"id":"HP-030","tab":"Homepage","section":"Persuasion & content","checkpoint":"Single-product brands: a story block, benefit icon grid (~6 icons), comparison table and multi-angle gallery are present","why":"The single-product wireframe sells the one hero product like a sales page.","how":"Compare the page with the single-product wireframe.","pass":"All four elements present.","ref":"Audit wireframes & workflows folder → 17-Single product homepage - desktop.pdf; Audit wireframes & workflows folder → 17-Single product homepage - mobile.pdf","importance":"Medium"},
  {"id":"HP-031","tab":"Homepage","section":"Persuasion & content","checkpoint":"A comparison (us vs. others, without naming competitors) highlights our column with checks on every row","why":"Answers 'why not a cheaper option?'.","how":"Find the comparison block; check it on mobile (swipe between competitors).","pass":"Our column highlighted; readable on phone.","ref":"Audit wireframes & workflows folder → 17-Single product homepage - desktop.pdf; Audit wireframes & workflows folder → 17-Single product homepage - mobile.pdf","importance":"Low"},
  {"id":"HP-032","tab":"Homepage","section":"Persuasion & content","checkpoint":"A 'Right for you if…' self-qualification block with a first-person CTA ('Yes, this is me') for problem-solving products","why":"Visitors who recognise themselves convert much better.","how":"Look for a qualifying checklist.","pass":"Checklist of situations + first-person CTA.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after) (Happy V)","importance":"Low"},
  {"id":"HP-033","tab":"Homepage","section":"Persuasion & content","checkpoint":"Best sellers are placed directly BELOW the 3-step transformation section","why":"The sheet's homepage order: hero → transformation → best sellers.","how":"List the first 4 sections.","pass":"Transformation, then best sellers.","ref":"Website Auditing Sheet – Home Page tab (row 10)","importance":"Medium"},
  {"id":"HP-034","tab":"Homepage","section":"Persuasion & content","checkpoint":"A section highlights the benefits customers can expect (image/icon + text)","why":"Interest stage of the homepage.","how":"Find a benefits section.","pass":"Clear benefits section.","ref":"Website Auditing Sheet – Home Page tab (row 11)","importance":"Medium"},
  {"id":"HP-035","tab":"Homepage","section":"Social proof","checkpoint":"A dedicated reviews section shows ~3 testimonials with photo, stars, name and quote (swipe carousel on mobile)","why":"Desire comes from seeing people like you succeed.","how":"Find the social proof section.","pass":"Real names, photos, specific outcomes; works on mobile.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Website Auditing Sheet – Home Page tab (row 12)","importance":"High"},
  {"id":"HP-036","tab":"Homepage","section":"Social proof","checkpoint":"An aggregate rating ('4.8/5 from 2,300 reviews') + CTA follows the testimonials","why":"Converts trust into action immediately.","how":"Look under the testimonials.","pass":"Aggregate rating and button.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf","importance":"Medium"},
  {"id":"HP-037","tab":"Homepage","section":"Social proof","checkpoint":"Testimonials describe outcomes ('I finally sleep through the night'), not just praise ('Great product')","why":"Outcome stories sell; generic praise doesn't.","how":"Read 5 testimonials.","pass":"Most mention a specific result.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.8)","importance":"Medium"},
  {"id":"HP-038","tab":"Homepage","section":"Social proof","checkpoint":"Reviews are clearly real: names, dates, 'Verified buyer' tags, some photos; no copy-pasted or template testimonials","why":"Fake-looking reviews destroy trust. A past audit found template testimonials live on a client site.","how":"Check names/photos; reverse-image-search one photo.","pass":"Verified, dated reviews with real photos.","ref":"Audit wireframes & workflows folder → Examples → Home Page (Ritual, GHOST, OPositiv, Happy V before/after); Optimizers past audit (Inventel)","importance":"Critical"},
  {"id":"HP-039","tab":"Homepage","section":"Social proof","checkpoint":"A UGC / Instagram image strip (horizontal scroller desktop, grid mobile) shows real customers using the product","why":"Real-life photos make the product feel proven.","how":"Scroll near the FAQ.","pass":"5–7 real customer images, not stock.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Website Auditing Sheet – Home Page tab (row 15)","importance":"Low"},
  {"id":"HP-040","tab":"Homepage","section":"FAQ, closing & footer","checkpoint":"An FAQ accordion (~6 questions) answers ordering, shipping, returns, payment and product questions before the footer","why":"Objections left unanswered become exits.","how":"Open every question; read the answers.","pass":"≥5 real questions with short, specific answers.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → AIDA Framework by Oliver Kenyon.pdf (p.9); Website Auditing Sheet – Home Page tab (row 14)","importance":"Medium"},
  {"id":"HP-041","tab":"Homepage","section":"FAQ, closing & footer","checkpoint":"A closing section repeats rating + emotive headline + CTA (+ testimonial or payment logos) just before the footer","why":"The page must never end without a way to act ('Bond movie that turns off before the end').","how":"Scroll to the bottom.","pass":"Final CTA block present.","ref":"Audit wireframes & workflows folder → 01-Homepage - desktop.pdf; Assets → AIDA Framework by Oliver Kenyon.pdf (p.10)","importance":"High"},
  {"id":"HP-042","tab":"Homepage","section":"FAQ, closing & footer","checkpoint":"USP strip is repeated just above the footer","why":"Final reassurance for scrollers.","how":"Look above the footer.","pass":"USP strip repeated.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy)","importance":"Low"},
  {"id":"HP-043","tab":"Homepage","section":"FAQ, closing & footer","checkpoint":"Footer has link columns (site map, policies, contact), newsletter field + button, social icons, payment logos; columns become accordions on mobile","why":"Standard trust + navigation; accordions keep the mobile footer short.","how":"Inspect the footer on both devices; subscribe with a test email.","pass":"All present; newsletter signup works.","ref":"Assets → High Conversion Rate Homepage - Desktop.PNG (annotated anatomy); Audit wireframes & workflows folder → 17-Single product homepage - desktop.pdf","importance":"Medium"},
  {"id":"HP-044","tab":"Homepage","section":"Homepage on mobile","checkpoint":"Mobile header is reduced to hamburger + centred logo + cart (search reachable in one tap)","why":"Keeps the header compact without losing key functions.","how":"Open on a phone.","pass":"Matches description; search reachable.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf","importance":"Low"},
  {"id":"HP-045","tab":"Homepage","section":"Homepage on mobile","checkpoint":"Grids reflow correctly: 4 products → 2×2, 3 categories → 1 per row, 3 steps → stacked, 3 reviews → swipe carousel","why":"Squeezed desktop grids make text unreadable and buttons untappable.","how":"Scroll the whole page on a phone.","pass":"Nothing tiny, cut off or sideways-scrolling.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Audit wireframes & workflows folder → 17-Single product homepage - mobile.pdf","importance":"Medium"},
  {"id":"HP-046","tab":"Homepage","section":"Homepage on mobile","checkpoint":"Mobile keeps the same persuasion order as desktop (proof → transformation → products → content → reviews → FAQ → closing CTA)","why":"Hiding sections on mobile removes the arguments mobile visitors need most.","how":"Compare section lists on both devices.","pass":"Same sections and order.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf vs Audit wireframes & workflows folder → 01-Homepage - desktop.pdf","importance":"Medium"},
  {"id":"HP-047","tab":"Homepage","section":"Homepage on mobile","checkpoint":"All mobile CTAs are near full width and at least 44px tall","why":"Thumb-friendly buttons get tapped; small ones get missed.","how":"Tap every main button on a phone.","pass":"Easy to tap first time.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; Audit wireframes & workflows folder → 17-Single product homepage - mobile.pdf","importance":"Medium"},
  {"id":"HP-048","tab":"Homepage","section":"Single-product homepage","checkpoint":"Hero: benefit-driven value proposition + star rating, quick product description, 3 benefit bullets, CTA anchored with payment seals, product image on the right, nav links top left","why":"The sheet's above-the-fold formula for single-product brands.","how":"Tick each element in the first screen.","pass":"All present.","ref":"Website Auditing Sheet – Single product homepage tab (row 1–6); Audit wireframes & workflows folder → 17-Single product homepage","importance":"High"},
  {"id":"HP-049","tab":"Homepage","section":"Single-product homepage","checkpoint":"A detailed product section built from customer survey answers (why they bought, what they love)","why":"Real customer reasons are the most persuasive arguments.","how":"Find a detailed 'why customers choose us' section; ask the client if it came from survey data.","pass":"Section exists and uses real survey insights.","ref":"Website Auditing Sheet – Single product homepage tab (row 10)","importance":"Medium"},
  {"id":"HP-050","tab":"Homepage","section":"Single-product homepage","checkpoint":"Benefit icons with text, social proof (comment, image, rating, full name), CTA with proof + trust, comparison vs competitor with product image, FAQ, and a visual section showing the product in different positions","why":"Remaining sheet criteria for single-product homepages.","how":"List the sections.","pass":"All present.","ref":"Website Auditing Sheet – Single product homepage tab (row 7–15); Audit wireframes & workflows folder → 17-Single product homepage","importance":"Medium"},
  {"id":"CL-001","tab":"Collection Page","section":"Collection header","checkpoint":"The collection opens with a short banner: emotive headline, collection-level rating (e.g. 4.8/5 from N reviews) and 1–2 lines of description","why":"Tells visitors they are in the right place and that customers love this range.","how":"Open the 2 audited collections on both devices.","pass":"Headline + rating + short copy; banner is not taller than ~1/3 of the first screen.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf; Website Auditing Sheet – Collection Page tab (row 2–3)","importance":"Medium"},
  {"id":"CL-002","tab":"Collection Page","section":"Collection header","checkpoint":"Products appear in the first screen on mobile (the banner doesn't push the grid below the fold)","why":"Visitors came to see products; a tall banner delays them.","how":"Open on a phone without scrolling.","pass":"At least the top of the first product row visible.","ref":"Audit wireframes & workflows folder → 03-Collection page - mobile.pdf; Website Auditing Sheet – Collection Page tab (row 1, 4)","importance":"High"},
  {"id":"CL-003","tab":"Collection Page","section":"Collection header","checkpoint":"Product count ('32 products') is shown","why":"Sets expectations for browsing.","how":"Look above the grid.","pass":"Count visible.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf","importance":"Low"},
  {"id":"CL-004","tab":"Collection Page","section":"Collection header","checkpoint":"Breadcrumb or clear page title shows where the visitor is","why":"Orientation, especially for visitors coming from ads or Google.","how":"Look above the grid.","pass":"Clear title/breadcrumb.","ref":"","importance":"Low"},
  {"id":"CL-005","tab":"Collection Page","section":"Collection header","checkpoint":"Desktop shows as many products as possible above the fold; no large white space above the grid","why":"Sheet comment: 'a lot of white space above the fold'.","how":"Open on a laptop without scrolling; count visible products.","pass":"At least one full row of products visible.","ref":"Website Auditing Sheet – Collection Page tab (row 1); Website Auditing Sheet – Collection Page tab (row 4)","importance":"High"},
  {"id":"CL-006","tab":"Collection Page","section":"Filters & sorting","checkpoint":"Sort control (best selling, price, newest, top rated) sits top-right of the grid and defaults to 'Best selling' or 'Featured'","why":"Default order decides what most people see; best sellers convert better than alphabetical.","how":"Check sort options and the default.","pass":"Useful options; sensible default.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf","importance":"Medium"},
  {"id":"CL-007","tab":"Collection Page","section":"Filters & sorting","checkpoint":"Desktop: left-sidebar filter accordions; Mobile: horizontally scrollable filter chips or a filter drawer","why":"Filters help large catalogues; they must be easy to use on a phone.","how":"Apply 2 filters on each device, then clear them.","pass":"Filters apply quickly, show counts, can be cleared in one tap.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf","importance":"Medium"},
  {"id":"CL-008","tab":"Collection Page","section":"Filters & sorting","checkpoint":"Filters match how customers choose (skin type, size, scent, concern, price) and never return empty results","why":"Irrelevant filters are ignored; zero-result filters frustrate.","how":"Try each filter option.","pass":"Relevant filters; every option returns products.","ref":"","importance":"Medium"},
  {"id":"CL-009","tab":"Collection Page","section":"Filters & sorting","checkpoint":"Sub-category quick chips (e.g. 'Slides / Sandals / Slingbacks') at the top of large collections","why":"One-tap narrowing on mobile.","how":"Look above the grid on a phone.","pass":"Chips present and working.","ref":"Audit wireframes & workflows folder → IMG_8333.PNG (collection image-swap case: +$12,382/month)","importance":"Low"},
  {"id":"CL-010","tab":"Collection Page","section":"Filters & sorting","checkpoint":"On mobile, filters are compact (one chip row or a 'Filter' button) and do not push products below the fold; about 2 products visible per scroll","why":"Sheet comment: 'Filters are taking a large space pushing products below the fold'.","how":"Open on a phone.","pass":"Filter UI ≤1 line; products visible.","ref":"Website Auditing Sheet – Collection Page tab (row 1)","importance":"High"},
  {"id":"CL-011","tab":"Collection Page","section":"Product cards","checkpoint":"Every card shows: image, star rating + score, product name, price ('From X' for variants)","why":"Shoppers compare on these four things without opening each product.","how":"Inspect 5 cards.","pass":"All four on every card.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf; Website Auditing Sheet – Collection Page tab (row 6)","importance":"High"},
  {"id":"CL-012","tab":"Collection Page","section":"Product cards","checkpoint":"Card titles are clear and benefit-led where possible (not internal SKU codes)","why":"Names must explain what the product is.","how":"Read 10 card titles.","pass":"Understandable names.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf","importance":"Medium"},
  {"id":"CL-013","tab":"Collection Page","section":"Product cards","checkpoint":"Images have the same ratio and style across the grid; product is clearly visible","why":"A consistent grid looks professional and is easy to scan.","how":"Scroll the grid.","pass":"Uniform, clean images.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → IMG_8333.PNG (collection image-swap case: +$12,382/month)","importance":"Low"},
  {"id":"CL-014","tab":"Collection Page","section":"Product cards","checkpoint":"A second image on hover (desktop) or swipe/indicator (mobile) shows another angle or the product in use","why":"Reported result in the reference case: +$12,382 per month from adding swappable images to collection cards.","how":"Hover a card on desktop; swipe one on a phone.","pass":"Second image appears; indicator visible.","ref":"Audit wireframes & workflows folder → IMG_8333.PNG (collection image-swap case: +$12,382/month)","importance":"High"},
  {"id":"CL-015","tab":"Collection Page","section":"Product cards","checkpoint":"Every card has a direct 'Add to cart' (and optional 'View product'); variant products open a quick variant picker","why":"Removes a step for buyers who already know what they want.","how":"Click add-to-cart on single- and multi-variant products.","pass":"Product added (or variant picker opens); cart count updates.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf; Website Auditing Sheet – Collection Page tab (row 6)","importance":"High"},
  {"id":"CL-016","tab":"Collection Page","section":"Product cards","checkpoint":"Quick-add / quick view actually works and shows the full product details (price, variants, description, reviews)","why":"Reviewer comment on the original audit sheet; a past audit found quick-add silently failing.","how":"Open quick view on 3 products and add to cart.","pass":"Complete details; add-to-cart succeeds every time.","ref":"Website Auditing Sheet - Product Page (additional comments); Optimizers past audit (Tharaa)","importance":"Critical"},
  {"id":"CL-017","tab":"Collection Page","section":"Product cards","checkpoint":"Honest badges ('Selling fast', 'New', '-20%') used on a few cards, not all","why":"Selective badges draw the eye; universal badges are noise.","how":"Count badges.","pass":"Badges on a minority of cards; all true.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Website Auditing Sheet – Collection Page tab (row 5)","importance":"Low"},
  {"id":"CL-018","tab":"Collection Page","section":"Product cards","checkpoint":"Sale cards show the original price crossed out next to the sale price","why":"Makes savings visible at a glance.","how":"Find a discounted product.","pass":"Compare-at price visible.","ref":"","importance":"Medium"},
  {"id":"CL-019","tab":"Collection Page","section":"Product cards","checkpoint":"Out-of-stock products are labelled clearly and pushed to the end (or hidden)","why":"Clicking into a sold-out product is a dead end.","how":"Look for sold-out items.","pass":"Labelled and last.","ref":"","importance":"Medium"},
  {"id":"CL-020","tab":"Collection Page","section":"Product cards","checkpoint":"Colour/variant swatches on cards where colour is a key choice","why":"Shows the range without opening every product.","how":"Check fashion/colour products.","pass":"Swatches visible and switch the image.","ref":"","importance":"Low"},
  {"id":"CL-021","tab":"Collection Page","section":"Grid & paging","checkpoint":"Desktop grid 3–4 columns; mobile grid 2 columns with readable text and tappable buttons","why":"Too many/too few columns make browsing slow.","how":"Check both devices.","pass":"3–4 desktop / 2 mobile.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf","importance":"Medium"},
  {"id":"CL-022","tab":"Collection Page","section":"Grid & paging","checkpoint":"Load more / pagination works, keeps filters, and the back button returns to the same scroll position","why":"Losing your place after viewing a product makes people give up.","how":"Load page 2, open a product, press Back.","pass":"Returns to the same spot with filters kept.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Website Auditing Sheet – Collection Page tab (row 8)","importance":"High"},
  {"id":"CL-023","tab":"Collection Page","section":"Grid & paging","checkpoint":"Promo / editorial blocks after the grid support the collection (bundle, guide, story) — not random banners","why":"Adds context and AOV ideas.","how":"Scroll below the grid.","pass":"Relevant blocks.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf","importance":"Low"},
  {"id":"CL-024","tab":"Collection Page","section":"Grid & paging","checkpoint":"A cross-sell row ('Explore by series' / related collections) sits before the footer","why":"Gives browsers another path instead of leaving.","how":"Scroll to the bottom.","pass":"Related collections or products shown.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf; Website Auditing Sheet – Collection Page tab (row 7)","importance":"Low"},
  {"id":"CL-025","tab":"Collection Page","section":"Collection SEO & content","checkpoint":"A short, helpful text block (below the grid) explains the collection and links to guides","why":"Helps SEO and undecided shoppers without pushing products down.","how":"Scroll below the grid.","pass":"100–300 words of useful copy, not keyword stuffing.","ref":"","importance":"Low"},
  {"id":"CL-026","tab":"Collection Page","section":"Consistency","checkpoint":"Announcement bar, header, USP strip and footer are identical to the homepage and PDP","why":"Inconsistent elements look like a different site.","how":"Compare with the homepage.","pass":"Same on all pages.","ref":"Audit wireframes & workflows folder → 03-Collection page - desktop.pdf; Audit wireframes & workflows folder → 03-Collection page - mobile.pdf","importance":"Low"},
  {"id":"PDP-001","tab":"Product Page","section":"Header & bars","checkpoint":"Navigation on the PDP has max 5 top-level links (see Sitewide tab for detail)","why":"Fewer exits from the product page.","how":"Count menu links on a PDP.","pass":"≤5 links.","ref":"Website Auditing Sheet - Product Page (row 1)","importance":"Medium"},
  {"id":"PDP-002","tab":"Product Page","section":"Header & bars","checkpoint":"A dynamic notice bar shows a current sale / free shipping / promotion message on the PDP","why":"Removes cost doubt on the page where people decide.","how":"Read the bar on 3 PDPs.","pass":"Current, concrete message.","ref":"Website Auditing Sheet - Product Page (row 2); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-003","tab":"Product Page","section":"Header & bars","checkpoint":"Only ONE offer message is visible (no promo bar + floating '20% off' tab + pop-up competing)","why":"Competing offers confuse and cover the buy box.","how":"Load a PDP fresh on a phone; wait 15 s.","pass":"One clear offer.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"High"},
  {"id":"PDP-004","tab":"Product Page","section":"Header & bars","checkpoint":"A trust/policy bar (shipping, returns, reviews, support) sits under the header; one-line ticker on mobile","why":"Highlights where the brand earns positive feedback.","how":"Look under the header.","pass":"4 icon promises.","ref":"Website Auditing Sheet - Product Page (row 3); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-005","tab":"Product Page","section":"Header & bars","checkpoint":"Payment plans / BNPL (valU, Tabby, Tamara, AfterPay…) are shown close to the CTA if offered","why":"Reviewer comment on the audit sheet: 'Add payment plans close to the CTA'. Splitting the price lowers the barrier.","how":"Look within one thumb-scroll of add-to-cart.","pass":"'Or 4 payments of X with …' near the price/CTA.","ref":"Website Auditing Sheet - Product Page (row 3) comments; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.2)","importance":"High"},
  {"id":"PDP-006","tab":"Product Page","section":"Gallery","checkpoint":"Clear, high-quality images from multiple angles and in different settings (packshot, in use, scale, details, texture)","why":"Online shoppers can't touch the product; images replace the shop floor.","how":"Open the gallery; count image types.","pass":"≥5 images incl. lifestyle and detail shots.","ref":"Website Auditing Sheet - Product Page (row 4); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-007","tab":"Product Page","section":"Gallery","checkpoint":"Gallery includes infographic images (benefits, how to use, ingredients) and UGC photos, not only packshots","why":"Images get looked at more than text.","how":"Swipe through all images.","pass":"At least 1 infographic and 1 real-customer image.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after); Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.3)","importance":"Medium"},
  {"id":"PDP-008","tab":"Product Page","section":"Gallery","checkpoint":"Thumbnails (desktop) or dots/peek + arrows (mobile) show there are more images","why":"Hidden images are never seen.","how":"Check gallery controls on both devices.","pass":"Visible thumbnails/arrows/dots.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Low"},
  {"id":"PDP-009","tab":"Product Page","section":"Gallery","checkpoint":"Images zoom on click/pinch and are sharp; first image loads fast","why":"Blurry or slow images look cheap.","how":"Zoom on desktop and pinch on phone.","pass":"Sharp zoom; image loads under ~2 s.","ref":"","importance":"Medium"},
  {"id":"PDP-010","tab":"Product Page","section":"Gallery","checkpoint":"On mobile the gallery is not so tall that the price and CTA disappear below the first screen","why":"An oversized gallery pushing the CTA down was found in a past audit.","how":"Open on a phone without scrolling.","pass":"Title and price at least partly visible; CTA within one short scroll.","ref":"Optimizers past audit (Balqees)","importance":"High"},
  {"id":"PDP-011","tab":"Product Page","section":"Gallery","checkpoint":"A product video (demo / UGC) is available in the gallery or near the top","why":"Video shows texture, size and use better than photos.","how":"Look for a video thumbnail.","pass":"Short video present.","ref":"Audit wireframes & workflows folder → CW_I_Sept_25_I_Purau_U_Above_The_Fold_(3).webp (product page anatomy)","importance":"Low"},
  {"id":"PDP-012","tab":"Product Page","section":"Gallery","checkpoint":"Selecting a variant switches the gallery to that variant's image","why":"Shows exactly what the customer will receive.","how":"Click each colour/variant.","pass":"Image updates.","ref":"","importance":"Medium"},
  {"id":"PDP-013","tab":"Product Page","section":"Buy box","checkpoint":"Social proof like '★★★★★ 4.8 out of 5 from 10,000 happy customers' sits ABOVE the title and close to the CTA","why":"Reviewer comment: 'Bring the reviews closer to the CTA'. All reference examples move the rating above the title.","how":"Look at the top of the buy box.","pass":"Rating line above the title, linking to the reviews section.","ref":"Website Auditing Sheet - Product Page (row 5); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"High"},
  {"id":"PDP-014","tab":"Product Page","section":"Buy box","checkpoint":"The rating line is written as a claim ('Rated 4.7/5 by 20,000+ customers'), not just '2981 reviews'","why":"A claim reads as proof; a bare count is easy to ignore.","how":"Read the rating line.","pass":"Score + quantified customers.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Medium"},
  {"id":"PDP-015","tab":"Product Page","section":"Buy box","checkpoint":"The value proposition is prominent: benefit-led title or a one-line promise right under the product name","why":"Sheet row 6 was rated 'badly' — the product name alone doesn't sell.","how":"Read the title + first line.","pass":"Visitor understands the main benefit without scrolling.","ref":"Website Auditing Sheet - Product Page (row 6); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"High"},
  {"id":"PDP-016","tab":"Product Page","section":"Buy box","checkpoint":"A short one-sentence description follows the title with key claims in bold","why":"Fast scanners read only bold text.","how":"Read under the title.","pass":"One sentence, bolded key claim.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Low"},
  {"id":"PDP-017","tab":"Product Page","section":"Buy box","checkpoint":"Price is clearly visible next to the title ('From X' when variants differ), in the local currency","why":"Hidden or unclear prices create doubt.","how":"Check price on all variants.","pass":"Correct, clear price; updates with variant.","ref":"Website Auditing Sheet - Product Page (row 7); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Critical"},
  {"id":"PDP-018","tab":"Product Page","section":"Buy box","checkpoint":"A REAL scarcity or time element sits near the price (low-stock count, sale end countdown, delivery cut-off)","why":"Reviewer comment: 'Scarcity factor should be implemented'. It gives a reason to buy now — but fake urgency destroys trust.","how":"Look near the price. Ask the client whether stock/deadline numbers are real.","pass":"e.g. 'Only 7 left' from real inventory, or 'Order in 3h for delivery tomorrow'.","ref":"Website Auditing Sheet - Product Page (row 7); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"High"},
  {"id":"PDP-019","tab":"Product Page","section":"Buy box","checkpoint":"Sale price shows the original price crossed out and the saving ('Save 25%' / 'Save 100 EGP')","why":"Makes the deal visible.","how":"Check a discounted product.","pass":"Compare-at + saving badge.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after); Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.9)","importance":"Medium"},
  {"id":"PDP-020","tab":"Product Page","section":"Buy box","checkpoint":"The description is converted into THREE benefit-driven bullet points with check icons, outcome words in bold","why":"Sheet row 8 was 'Not implemented'. Bullets convey value in 3 seconds.","how":"Look under the price.","pass":"3 short benefit bullets (not features).","ref":"Website Auditing Sheet - Product Page (row 8); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"High"},
  {"id":"PDP-021","tab":"Product Page","section":"Buy box","checkpoint":"Variant options (colour, size, scent) are visible button tiles or swatches — not hidden in a dropdown","why":"Visible options are easier to compare and choose. The GHOST example replaced a dropdown with tiles.","how":"Look at the variant selector.","pass":"Tiles/swatches with a label above.","ref":"Website Auditing Sheet - Product Page (row 9); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Medium"},
  {"id":"PDP-022","tab":"Product Page","section":"Buy box","checkpoint":"The selected variant is clearly highlighted; unavailable variants are crossed out (not hidden)","why":"Prevents wrong orders and confusion.","how":"Click through variants.","pass":"Clear selected state; sold-out shown as such.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Medium"},
  {"id":"PDP-023","tab":"Product Page","section":"Buy box","checkpoint":"Size/fit guide or 'which one is right for me' helper is next to the variant selector (where relevant)","why":"Wrong-size fear stops purchases and causes returns.","how":"Look next to size options.","pass":"Size guide link/pop-up.","ref":"","importance":"Medium"},
  {"id":"PDP-024","tab":"Product Page","section":"Buy box","checkpoint":"Bundle / quantity tiers (1 / 2 / 3) with escalating savings; middle tier tagged 'Most popular', top tier 'Best value'","why":"The PuraU case raised CVR from 2% to 7% partly via a 3-option bundle where 2 options anchor the middle one.","how":"Check whether the product can be sold in multiples.","pass":"3 tiers with savings and tags; contents listed.","ref":"Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.9); Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after) (URO)","importance":"Medium"},
  {"id":"PDP-025","tab":"Product Page","section":"Buy box","checkpoint":"Subscribe-and-save vs one-time purchase shown as radio cards with saving badge and 'Cancel anytime' (for consumables)","why":"Raises lifetime value and lowers price perception.","how":"Check consumable products.","pass":"Two clear options; reassurance line.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after) (Ritual, GHOST)","importance":"Low"},
  {"id":"PDP-026","tab":"Product Page","section":"Buy box","checkpoint":"Quantity selector sits next to a full-width, high-contrast Add-to-cart button with a clear label","why":"The one action that matters must be impossible to miss.","how":"Squint at the buy box.","pass":"Button is the most visible element.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Critical"},
  {"id":"PDP-027","tab":"Product Page","section":"Buy box","checkpoint":"Add-to-cart gives instant feedback (drawer opens / message / count updates) and never fails silently","why":"Uncertainty after clicking causes double orders or exits.","how":"Click add-to-cart on 3 products, on both devices.","pass":"Clear confirmation every time.","ref":"Optimizers past audit (Tharaa)","importance":"Critical"},
  {"id":"PDP-028","tab":"Product Page","section":"Buy box","checkpoint":"Payment seals (Visa, Mastercard, Apple Pay, COD, BNPL) + 'Secure checkout' are anchored directly under the CTA","why":"Reviewer comment: 'Should be anchored close to CTA'. Security reassurance at the click moment.","how":"Look directly under/above the button.","pass":"Icons touching the CTA area, not in the footer only.","ref":"Website Auditing Sheet - Product Page (row 10); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"High"},
  {"id":"PDP-029","tab":"Product Page","section":"Buy box","checkpoint":"Delivery details: specific timing ('Order in 3h → delivered Thursday'), estimated duration, and free-shipping threshold BELOW the delivery time","why":"Reviewer comment: 'Free shipping should be included below delivery time'. Unknown delivery is a top abandonment reason.","how":"Look below the CTA.","pass":"Delivery estimate + shipping cost/free threshold.","ref":"Website Auditing Sheet - Product Page (row 11); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"High"},
  {"id":"PDP-030","tab":"Product Page","section":"Buy box","checkpoint":"A reassurance box below the CTA: delivery, returns/guarantee, support (3 icon rows)","why":"Answers the last doubts at the decision point.","how":"Look under the payment icons.","pass":"3 icon rows with short text.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-031","tab":"Product Page","section":"Buy box","checkpoint":"A money-back / satisfaction guarantee is visible near the buy box (if the store offers one)","why":"Risk reversal.","how":"Look near the CTA.","pass":"Guarantee with number of days.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Medium"},
  {"id":"PDP-032","tab":"Product Page","section":"Buy box","checkpoint":"A mini testimonial (photo, first + last name, stars, short quote) sits in or under the buy box","why":"Sheet row 12: real social proof with images and names enhances credibility.","how":"Look under the reassurance box.","pass":"Real photo + full name + quote.","ref":"Website Auditing Sheet - Product Page (row 12); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-033","tab":"Product Page","section":"Buy box","checkpoint":"Description / details / ingredients / shipping in tabs (desktop) or accordions (mobile), first one open","why":"Keeps the buy box short while giving all details.","how":"Open each tab/accordion.","pass":"Organised, complete info.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-034","tab":"Product Page","section":"Buy box","checkpoint":"Floating widgets (chat, WhatsApp, discount tab, cookie banner) never cover the variant picker, price or CTA","why":"Fixed in two of the reference examples.","how":"Scroll the buy box on a phone.","pass":"Nothing covers buying controls.","ref":"Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"High"},
  {"id":"PDP-035","tab":"Product Page","section":"Buy box","checkpoint":"Sticky add-to-cart bar appears on mobile once the main button scrolls out of view","why":"Keeps buying one tap away on long pages (gap not drawn in the wireframes but standard practice).","how":"Scroll down a PDP on a phone.","pass":"Sticky bar with price + button; doesn't cover content.","ref":"Not in wireframes — best practice","importance":"Medium"},
  {"id":"PDP-036","tab":"Product Page","section":"Buy box","checkpoint":"Mobile buy-box order: rating → title → price + stock → bullets → variants → secure line → qty + CTA → payment icons","why":"The wireframe's mobile order puts persuasion before the button.","how":"Compare with the mobile wireframe.","pass":"Same order.","ref":"Audit wireframes & workflows folder → 02-Product page - mobile.pdf; Audit wireframes & workflows folder → Examples → PDP (Ritual, GHOST, URO before/after)","importance":"Medium"},
  {"id":"PDP-037","tab":"Product Page","section":"Trust (authority)","checkpoint":"Authentic brands / press / retailers the brand has worked with are shown ('As recommended by')","why":"Sheet row 13 'Not implemented'. Borrowed trust.","how":"Scroll below the buy box.","pass":"Real logos or press quote.","ref":"Website Auditing Sheet - Product Page (row 13); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.3)","importance":"Medium"},
  {"id":"PDP-038","tab":"Product Page","section":"Transformation","checkpoint":"A transformation section with 3 clear steps: how to order → delivery speed → the benefit received","why":"Sheet row 14 'Not implemented'. Explain it 'as if speaking to a 6-year-old'.","how":"Look for a 3-step icon row.","pass":"3 steps with icons and 1–2 lines each.","ref":"Website Auditing Sheet - Product Page (row 14); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.4)","importance":"High"},
  {"id":"PDP-039","tab":"Product Page","section":"Interest — benefits","checkpoint":"A benefits section with supporting images (alternating image/text rows) — short copy, outcomes only","why":"Sheet row 15 'Not implemented'. Sparks interest before features.","how":"Find the benefits block.","pass":"2–4 benefit rows with images.","ref":"Website Auditing Sheet - Product Page (row 15); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.5)","importance":"High"},
  {"id":"PDP-040","tab":"Product Page","section":"Interest — features","checkpoint":"A features / ingredients section with images; every feature statement ends with the benefit it delivers","why":"Sheet row 16 'Not implemented'. Features justify the benefits.","how":"Find the features block.","pass":"Image-led features, each tied to a benefit; link to proof/research if available.","ref":"Website Auditing Sheet - Product Page (row 16); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.6)","importance":"Medium"},
  {"id":"PDP-041","tab":"Product Page","section":"Interest — features","checkpoint":"A 'How to use' visual (steps or short video) is on the page","why":"Answers 'is it complicated?' — a common objection.","how":"Search the page for usage instructions.","pass":"Simple steps/visual.","ref":"","importance":"Medium"},
  {"id":"PDP-042","tab":"Product Page","section":"Action (mid-page)","checkpoint":"A CTA directly below the features with star rating and payment seals","why":"Sheet row 17 'Not implemented'. Catches visitors convinced by the features.","how":"Look right after features.","pass":"Stars + CTA + payment seals.","ref":"Website Auditing Sheet - Product Page (row 17); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-043","tab":"Product Page","section":"What's included","checkpoint":"'What's included' section shows every item in a bundle/package (with image and short list)","why":"Sheet row 18 'Implemented badly'. People need to know exactly what arrives.","how":"Find the section on bundle products.","pass":"Clear list + image of all contents.","ref":"Website Auditing Sheet - Product Page (row 18); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.9)","importance":"Medium"},
  {"id":"PDP-044","tab":"Product Page","section":"Desire — reviews","checkpoint":"Social proof section with star ratings, comments, customer images and user names","why":"Sheet row 19 'Not implemented'.","how":"Find the reviews section.","pass":"Reviews with stars, text, photos and names.","ref":"Website Auditing Sheet - Product Page (row 19); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.8)","importance":"High"},
  {"id":"PDP-045","tab":"Product Page","section":"Desire — reviews","checkpoint":"Reviews widget shows total count, rating breakdown, filters/sort, 'Write a review', dates; includes some 3–4★ reviews","why":"Mixed ratings look genuine; perfect 5.0 looks fake.","how":"Inspect the reviews app.","pass":"Full widget; realistic distribution.","ref":"Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.8)","importance":"Medium"},
  {"id":"PDP-046","tab":"Product Page","section":"Desire — reviews","checkpoint":"Products with zero/few reviews borrow proof (brand-level reviews, best-seller badge, guarantee) instead of showing an empty widget","why":"An empty review box signals 'nobody buys this'.","how":"Open the PDP with the fewest reviews.","pass":"No '0 reviews' emptiness.","ref":"","importance":"Medium"},
  {"id":"PDP-047","tab":"Product Page","section":"Desire — UGC","checkpoint":"User-generated content (customer videos / photos) is shown, e.g. a carousel of portrait video tiles","why":"Sheet row 20 'Not implemented'.","how":"Look for a UGC carousel.","pass":"Real customer videos/photos.","ref":"Website Auditing Sheet - Product Page (row 20); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-048","tab":"Product Page","section":"Action (after reviews)","checkpoint":"Another CTA with trust and payment seals after the social proof — use ONE consistent CTA label and colour everywhere","why":"Sheet row 21 comment: 'Only one consistent CTA'.","how":"Compare every CTA on the page.","pass":"Same label/colour; trust seals beside it.","ref":"Website Auditing Sheet - Product Page (row 21); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-049","tab":"Product Page","section":"Comparison","checkpoint":"A comparison section shows our advantages over competitors WITHOUT naming them ('Other brands')","why":"Sheet row 22 'Not implemented'. Answers 'why this over a cheaper one?'.","how":"Find the comparison.","pass":"Table or side-by-side with unnamed competitors.","ref":"Website Auditing Sheet - Product Page (row 22); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-050","tab":"Product Page","section":"Comparison","checkpoint":"Our column is larger, highlighted (dimmed background around it), with bigger icons and a check on every row","why":"Sheet row 23. Draws the eye to us.","how":"Look at the comparison styling; check mobile (swipe between competitors).","pass":"Clearly emphasised column; readable on phone.","ref":"Website Auditing Sheet - Product Page (row 23); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-051","tab":"Product Page","section":"FAQ / objections","checkpoint":"FAQ with at least 5–6 real questions covering: benefits, proof, how to use, shipping cost/time, returns, how often/how long","why":"Sheet row 24 comment: 'Only 1 question is in the FAQ section'. Unanswered doubts become exits.","how":"Open the FAQ; count and read answers.","pass":"≥6 questions with short, specific answers.","ref":"Website Auditing Sheet - Product Page (row 24); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.11)","importance":"High"},
  {"id":"PDP-052","tab":"Product Page","section":"FAQ / objections","checkpoint":"An objection block names who the product is for (conditions/problems) and confirms fit","why":"Visitors who scrolled this far are interested; reassure them it fits.","how":"Look before/after the FAQ.","pass":"'Right for you if…' style block + CTA.","ref":"Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.7)","importance":"Low"},
  {"id":"PDP-053","tab":"Product Page","section":"Desire — more UGC","checkpoint":"More UGC after the FAQ: additional reviews, images or videos (e.g. an Instagram-style strip)","why":"Sheet row 25 'Not implemented'.","how":"Scroll past the FAQ.","pass":"Strip of 5–7 real customer images.","ref":"Website Auditing Sheet - Product Page (row 25); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-054","tab":"Product Page","section":"Action (final)","checkpoint":"Another CTA with star reviews and payment seals near the end — the page never ends without a CTA","why":"Sheet row 26 'Not implemented'. 'Add another CTA so they can TAKE ACTION'.","how":"Scroll to the bottom.","pass":"Final CTA block with stars + seals.","ref":"Website Auditing Sheet - Product Page (row 26); Audit wireframes & workflows folder → 02-Product page - desktop.pdf; Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.12)","importance":"High"},
  {"id":"PDP-055","tab":"Product Page","section":"Cross-sell","checkpoint":"Upsell / downsell / cross-sell below the final CTA: related products with reviews and short descriptions","why":"Sheet row 27 'Implemented badly'. Raises AOV and gives undecided visitors an alternative.","how":"Look below the final CTA.","pass":"4 relevant products with stars, price, short line, quick add.","ref":"Website Auditing Sheet - Product Page (row 27); Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Medium"},
  {"id":"PDP-056","tab":"Product Page","section":"Cross-sell","checkpoint":"'Frequently bought together' / bundle suggestion near the buy box for complementary products","why":"Raises AOV at the moment of decision.","how":"Look under the CTA.","pass":"Relevant pairing with combined price.","ref":"","importance":"Low"},
  {"id":"PDP-057","tab":"Product Page","section":"Page structure","checkpoint":"Section order follows ATIDFA: Attention (buy box) → Transformation → Interest (benefits, features) → Desire (reviews, UGC, comparison) → FAQ → Action","why":"The framework every Optimizers wireframe uses.","how":"List the sections in order.","pass":"All stages present in this order.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf; Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"High"},
  {"id":"PDP-058","tab":"Product Page","section":"Page structure","checkpoint":"On mobile all sections stack cleanly; carousels show 1 item with arrows/dots; nothing is hidden compared with desktop","why":"Mobile visitors need the same arguments.","how":"Scroll the full PDP on a phone.","pass":"Same content, clean stacking.","ref":"Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"Medium"},
  {"id":"PDP-059","tab":"Product Page","section":"Page structure","checkpoint":"Repeated USP strip above the footer and complete footer as on other pages","why":"Consistency and final reassurance.","how":"Scroll to the footer.","pass":"Present.","ref":"Audit wireframes & workflows folder → 02-Product page - desktop.pdf","importance":"Low"},
  {"id":"CT-001","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"Adding a product opens a cart drawer (slide-in) or clear confirmation, not a silent page refresh","why":"Visitors must see the item was added and what to do next.","how":"Add from a PDP and from a collection card on both devices.","pass":"Drawer opens with the item.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"High"},
  {"id":"CT-002","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"Drawer header shows 'Your cart (N items)' and an obvious close (×); on mobile it covers the full width","why":"Clarity and easy exit back to shopping.","how":"Open the drawer on a phone.","pass":"Count + close visible; full width.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Low"},
  {"id":"CT-003","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"Sitewide offer / countdown repeats inside the drawer and matches the announcement bar","why":"Keeps the reason-to-buy visible at the last step.","how":"Compare the drawer bar with the site bar.","pass":"Same offer, same numbers.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-004","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"The page behind the cart drawer is dimmed (lower opacity overlay) so the drawer is the focus; clicking the overlay closes it","why":"Focuses attention on the cart and makes closing obvious.","how":"Open the drawer.","pass":"Background dimmed; overlay click closes.","ref":"Website Auditing Sheet – Cart Slider tab (row 1)","importance":"Low"},
  {"id":"CT-005","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"Empty drawer says it is empty and links to best sellers, top collections and suggested single products","why":"An empty drawer should restart shopping, not end it.","how":"Open the drawer with no items.","pass":"Empty message + product and collection links.","ref":"Website Auditing Sheet – Cart Slider tab (row 2)","importance":"Medium"},
  {"id":"CT-006","tab":"Cart Drawer & Cart","section":"Cart drawer basics","checkpoint":"The drawer is short: no excessive elements that force scrolling to reach the checkout button","why":"Scrolling inside a drawer adds friction (sheet row 6).","how":"Add 2 items on a phone; is checkout visible without scrolling the drawer?","pass":"Checkout visible or reachable with minimal scroll.","ref":"Website Auditing Sheet – Cart Slider tab (row 6)","importance":"Medium"},
  {"id":"CT-007","tab":"Cart Drawer & Cart","section":"Progress bar","checkpoint":"A progress bar shows how far the customer is from free shipping / a free gift, with the exact remaining amount","why":"'You're 120 EGP away from free shipping' raises AOV and reduces shipping shock.","how":"Add a cheap item; then add more until the threshold.","pass":"Exact amount; updates instantly; celebrates when reached.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after); Website Auditing Sheet – Cart Slider tab (row 3)","importance":"High"},
  {"id":"CT-008","tab":"Cart Drawer & Cart","section":"Progress bar","checkpoint":"The free-shipping threshold in the cart equals the one in the announcement bar and checkout","why":"Mismatch breaks trust at the last step.","how":"Compare all three.","pass":"Same amount everywhere.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"High"},
  {"id":"CT-009","tab":"Cart Drawer & Cart","section":"Progress bar","checkpoint":"Progress bar uses milestone icons (truck, gift) and encouraging copy ('Almost there!')","why":"Gamifies adding one more item.","how":"Look at the bar.","pass":"Icons + friendly copy.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Low"},
  {"id":"CT-010","tab":"Cart Drawer & Cart","section":"Line items","checkpoint":"Each item shows image, name, variant (size/colour/scent), purchase type and price (with compare-at if on sale)","why":"Customers check they picked the right thing.","how":"Inspect line items.","pass":"All details visible.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-011","tab":"Cart Drawer & Cart","section":"Line items","checkpoint":"Quantity stepper (−/+) and a separate trash/remove icon work instantly and update totals","why":"Editing should never require leaving the drawer.","how":"Change quantities and remove an item.","pass":"Totals update immediately, no errors.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"High"},
  {"id":"CT-012","tab":"Cart Drawer & Cart","section":"Line items","checkpoint":"Stepper +/− are in the correct order in Arabic/RTL layouts","why":"A mirrored stepper was found in a past audit and causes wrong orders.","how":"Switch to Arabic and test the stepper.","pass":"+ increases, − decreases.","ref":"Optimizers past audit (Balqees)","importance":"Medium"},
  {"id":"CT-013","tab":"Cart Drawer & Cart","section":"Line items","checkpoint":"Subscribe & save toggle in the cart for consumables","why":"Last chance to raise lifetime value.","how":"Look at line items of consumables.","pass":"Toggle with saving %.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Low"},
  {"id":"CT-014","tab":"Cart Drawer & Cart","section":"Upsells","checkpoint":"An upsell section with a benefit-led heading ('Complete your routine') shows ~2 relevant products, not a long list","why":"Too many upsells distract from checkout; 2 relevant ones raise AOV.","how":"Look under the line items.","pass":"≤2–3 compact, relevant products.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after); Website Auditing Sheet – Cart Slider tab (row 4)","importance":"Medium"},
  {"id":"CT-015","tab":"Cart Drawer & Cart","section":"Upsells","checkpoint":"Upsell cards show image, name, price (with saving), rating and a one-tap 'Add' button; variants selectable on the card","why":"One tap, no leaving the drawer.","how":"Add an upsell from the drawer.","pass":"Added without leaving the drawer.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-016","tab":"Cart Drawer & Cart","section":"Upsells","checkpoint":"Upsell buttons are visually secondary to the checkout button","why":"Checkout must stay the primary action.","how":"Squint at the drawer.","pass":"Checkout is the most visible button.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-017","tab":"Cart Drawer & Cart","section":"Summary","checkpoint":"Summary panel shows 'You saved X', subtotal and 'Shipping & taxes calculated at checkout' (or the actual shipping cost)","why":"Reinforces the deal and avoids shipping surprise.","how":"Read the summary.","pass":"Savings + subtotal + shipping note.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-018","tab":"Cart Drawer & Cart","section":"Summary","checkpoint":"Shipping cost (or how it is calculated) is visible BEFORE checkout — not first revealed on the payment step","why":"Hidden shipping cost on /cart was found in a past audit; surprise costs are the #1 abandonment reason.","how":"Check drawer and /cart page.","pass":"Shipping cost or rule visible.","ref":"Optimizers past audit (Balqees)","importance":"Critical"},
  {"id":"CT-019","tab":"Cart Drawer & Cart","section":"Summary","checkpoint":"Discount code field is either removed from the drawer (handled at checkout) or collapsed behind a small link","why":"A big empty coupon box sends people to search for codes and they don't come back.","how":"Look for a coupon field.","pass":"No prominent empty coupon field.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Medium"},
  {"id":"CT-020","tab":"Cart Drawer & Cart","section":"Summary","checkpoint":"If a discount code is applied, it works and the saving is visible before checkout","why":"Broken codes cause abandonment and support tickets.","how":"Apply the active code(s) from the Audit Setup tab.","pass":"Code applies; saving shown.","ref":"","importance":"High"},
  {"id":"CT-021","tab":"Cart Drawer & Cart","section":"Checkout button","checkpoint":"Checkout button is full width, high contrast, short secure label ('Checkout securely') and never covered by chat widgets","why":"The most important button of the whole site.","how":"Look on desktop and phone; scroll the drawer.","pass":"Dominant, uncovered button.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after)","importance":"Critical"},
  {"id":"CT-022","tab":"Cart Drawer & Cart","section":"Checkout button","checkpoint":"Payment / express icons (Visa, Mastercard, Apple Pay, COD, BNPL) sit directly under the checkout button","why":"Reassures right before payment.","how":"Look under the button.","pass":"Icons match methods available at checkout.","ref":"Audit wireframes & workflows folder → Examples → Cart (Ritual, GHOST, URO drawer before/after); Website Auditing Sheet – Cart Slider tab (row 5)","importance":"Medium"},
  {"id":"CT-023","tab":"Cart Drawer & Cart","section":"Checkout button","checkpoint":"Express checkout buttons (Shop Pay / Apple Pay / PayPal) available in the drawer where the platform supports it","why":"Skips the form for many mobile buyers.","how":"Look in the drawer.","pass":"Express buttons present and working.","ref":"","importance":"Low"},
  {"id":"CT-024","tab":"Cart Drawer & Cart","section":"Cart page (/cart)","checkpoint":"The /cart page mirrors the drawer: line items, progress bar, summary, shipping info, checkout + payment icons","why":"Some visitors land on /cart directly (from emails, back button).","how":"Visit /cart with items.","pass":"Same information and actions as the drawer.","ref":"","importance":"Medium"},
  {"id":"CT-025","tab":"Cart Drawer & Cart","section":"Cart page (/cart)","checkpoint":"Empty cart state shows best sellers / categories and a 'Continue shopping' button","why":"An empty dead-end page ends the visit.","how":"Remove all items.","pass":"Helpful empty state.","ref":"","importance":"Low"},
  {"id":"CT-026","tab":"Cart Drawer & Cart","section":"Cart page (/cart)","checkpoint":"Trust reminders near checkout: returns promise, guarantee, delivery time","why":"Last reassurance before payment.","how":"Look around the checkout button.","pass":"Short trust line(s).","ref":"","importance":"Low"},
  {"id":"CT-027","tab":"Cart Drawer & Cart","section":"Cart page (/cart)","checkpoint":"Cart contents persist after closing the browser and returning (same device)","why":"Many shoppers come back later to buy.","how":"Add items, close the tab, return after 5 minutes.","pass":"Items still there.","ref":"","importance":"Medium"},
  {"id":"CT-028","tab":"Cart Drawer & Cart","section":"Cart page (/cart)","checkpoint":"Gift message / order note field (if relevant to the category) is available but not in the way","why":"Important for gift purchases.","how":"Look in cart/checkout.","pass":"Optional field available.","ref":"Not in wireframes — best practice","importance":"Low"},
  {"id":"CO-001","tab":"Checkout","section":"Checkout entry","checkpoint":"Checkout opens in one click from the cart drawer and cart page, with no forced account creation","why":"Forced sign-up is one of the top reasons shoppers abandon checkout.","how":"Add a product, click Checkout from the drawer and from /cart. Note any login wall.","pass":"Guest checkout is the default; login is optional.","ref":"","importance":"Critical"},
  {"id":"CO-002","tab":"Checkout","section":"Checkout entry","checkpoint":"Express payment buttons (Apple Pay / Google Pay / Shop Pay / PayPal, as available) appear at the top of checkout","why":"Express options skip the form entirely for returning or mobile users.","how":"Open checkout on a phone; look above the contact form.","pass":"Express buttons visible above the fold where the market supports them.","ref":"","importance":"Medium"},
  {"id":"CO-003","tab":"Checkout","section":"Checkout copy","checkpoint":"Field labels are clear, in the customer's language, and say exactly what to type (e.g. 'Building number', 'Nearest landmark')","why":"Confusing labels cause errors and give-ups, especially for local address formats.","how":"Read every field label and placeholder in the checkout form.","pass":"No ambiguous labels; local address needs covered.","ref":"CRO board → Stage 4 step 5 (Audit the checkout copy)","importance":"High"},
  {"id":"CO-004","tab":"Checkout","section":"Checkout copy","checkpoint":"Error messages say what is wrong and how to fix it, next to the field, in plain language","why":"'Invalid input' errors make people give up.","how":"Submit the form with empty fields, a wrong email and a short phone number.","pass":"Each error appears beside the field with a specific fix ('Phone must be 11 digits').","ref":"","importance":"High"},
  {"id":"CO-005","tab":"Checkout","section":"Checkout copy","checkpoint":"Button text describes the next step ('Continue to shipping', 'Pay now', 'Place order') rather than 'Submit'","why":"Clear next steps reduce hesitation.","how":"Read every button label in checkout.","pass":"Action-specific button text throughout.","ref":"","importance":"Medium"},
  {"id":"CO-006","tab":"Checkout","section":"Checkout copy","checkpoint":"Shipping, payment and delivery wording is clear: cost, time and courier are stated before payment","why":"Surprise costs or unclear delivery times are the #1 checkout abandonment reason.","how":"Go to the shipping step; read the shipping options and the order summary.","pass":"Exact cost and delivery window shown before the payment step.","ref":"","importance":"Critical"},
  {"id":"CO-007","tab":"Checkout","section":"Checkout copy","checkpoint":"Trust and reassurance messages appear near the pay button (secure payment, returns, support contact)","why":"Reassurance at the moment of payment reduces last-second doubt.","how":"Look around the final pay/place-order button.","pass":"Short security + returns + help line near the button.","ref":"","importance":"Medium"},
  {"id":"CO-008","tab":"Checkout","section":"Checkout copy","checkpoint":"Cash-on-delivery (if offered) is clearly explained: any fee, and what happens at the door","why":"In markets like Egypt and the Gulf, COD clarity directly drives order completion.","how":"Select COD and read the description.","pass":"Fee (or 'no extra fee') and the process are explained.","ref":"","importance":"High"},
  {"id":"CO-009","tab":"Checkout","section":"Checkout flow","checkpoint":"Guest and logged-in checkout both work end to end; the number of steps and fields is minimal","why":"Every extra field lowers completion.","how":"Complete a test checkout as guest and as a logged-in user; count steps and fields.","pass":"Only fields needed to deliver and pay; no duplicate questions.","ref":"CRO board → Stage 4 step 6 (Audit the checkout flow)","importance":"High"},
  {"id":"CO-010","tab":"Checkout","section":"Checkout flow","checkpoint":"Form usability on mobile: correct keyboards (numeric for phone, email keyboard for email), autofill works, tap targets ≥44px","why":"Wrong keyboards and tiny fields create typing errors on phones.","how":"Fill the form on a real phone.","pass":"Right keyboard per field, browser autofill fills address, fields easy to tap.","ref":"","importance":"High"},
  {"id":"CO-011","tab":"Checkout","section":"Checkout flow","checkpoint":"Shipping options and payment methods offered match what the market expects (COD, wallets, cards, BNPL)","why":"A missing preferred payment method is an instant drop-off.","how":"List every shipping and payment option offered.","pass":"The locally popular methods are all available.","ref":"","importance":"High"},
  {"id":"CO-012","tab":"Checkout","section":"Checkout flow","checkpoint":"Order summary (products, images, quantities, discounts, shipping, total) is visible and easy to expand on mobile","why":"Shoppers re-check what they're paying for; hidden summaries create doubt.","how":"On a phone, find and open the order summary at each step.","pass":"Summary is one tap away and accurate.","ref":"","importance":"Medium"},
  {"id":"CO-013","tab":"Checkout","section":"Checkout flow","checkpoint":"No distractions: no main navigation, pop-ups or links that pull the shopper out of checkout","why":"Exits from checkout rarely come back.","how":"Look for menus, banners or links in checkout.","pass":"Logo + checkout only (Shopify checkout does this by default).","ref":"","importance":"Medium"},
  {"id":"CO-014","tab":"Checkout","section":"Checkout flow","checkpoint":"Discount-code field works, shows a clear success/error message, and is not so prominent that it sends people to search for codes","why":"A big empty coupon box makes shoppers leave to hunt for a code.","how":"Try a valid code and an invalid code.","pass":"Field is collapsible/subtle; messages are clear.","ref":"","importance":"Medium"},
  {"id":"CO-015","tab":"Checkout","section":"Checkout flow","checkpoint":"Thank-you page loads after payment with the order number and next steps (see Post-purchase tab)","why":"Confirms the purchase and reduces 'did it work?' support messages.","how":"Complete a test order.","pass":"Thank-you page with order number, summary and delivery info.","ref":"","importance":"Medium"},
  {"id":"CO-016","tab":"Checkout","section":"Checkout flow","checkpoint":"Each checkout finding is marked as a 'Copy change' (always possible) or a 'Layout change' (depends on platform, e.g. Shopify Plus)","why":"Layout changes are not possible on every platform; marking them sets realistic expectations.","how":"In the Recommendation column, start with [Copy] or [Layout].","pass":"Every checkout finding is tagged.","ref":"CRO board → Stage 4 'What can be changed' card","importance":"Medium"},
  {"id":"TY-001","tab":"Thank You & Post-Purchase","section":"Thank-you page","checkpoint":"Thank-you page shows the order number, items, total, delivery address and expected delivery date","why":"Confirms the order and cuts support enquiries.","how":"Place a test order and read the thank-you page.","pass":"All five details present.","ref":"","importance":"Medium"},
  {"id":"TY-002","tab":"Thank You & Post-Purchase","section":"Thank-you page","checkpoint":"Thank-you page tells the customer what happens next (confirmation SMS/email/WhatsApp, courier call, tracking)","why":"Removes post-purchase anxiety and reduces cancellations, especially for COD.","how":"Read the thank-you page text.","pass":"Clear next-step timeline.","ref":"","importance":"Medium"},
  {"id":"TY-003","tab":"Thank You & Post-Purchase","section":"Thank-you page","checkpoint":"Thank-you page offers a relevant next action (follow on social, refer a friend, one-click add-on, survey)","why":"The happiest moment of the journey is a chance to grow AOV or loyalty.","how":"Look for any post-purchase offer or survey.","pass":"One relevant, non-intrusive next action.","ref":"","importance":"Low"},
  {"id":"TY-004","tab":"Thank You & Post-Purchase","section":"Post-purchase","checkpoint":"Order confirmation message arrives within minutes and matches the order","why":"Delays or errors cause duplicate orders and cancellations.","how":"Check email/SMS/WhatsApp after the test order.","pass":"Confirmation within 5 minutes with correct details.","ref":"","importance":"Medium"},
  {"id":"TY-005","tab":"Thank You & Post-Purchase","section":"Post-purchase","checkpoint":"A review request is sent after delivery (not before) with a direct link to leave a review","why":"Reviews feed social proof on product pages; low-review products need an active request flow.","how":"Ask the client how reviews are collected; check the review app settings.","pass":"Automatic request after delivery with incentive if appropriate.","ref":"Optimizers past audit (Tharaa bundle had 5 reviews)","importance":"Medium"},
  {"id":"TY-006","tab":"Thank You & Post-Purchase","section":"Post-purchase","checkpoint":"A post-purchase survey asks 'What almost stopped you from buying?' and 'Where did you hear about us?'","why":"Answers feed the next CRO round with real objections and attribution.","how":"Check the thank-you page and confirmation emails for a survey.","pass":"Short survey in place.","ref":"","importance":"Low"},
  {"id":"MB-001","tab":"Mobile","section":"Mobile – first screen","checkpoint":"On a 390×844 phone, the first screen shows what the product/brand is, why it is worth it, and a visible CTA","why":"Most traffic is mobile; if the first screen doesn't answer 'what / why / what next', visitors leave.","how":"Open each audited page on a real phone (or Chrome DevTools device mode 390×844). Do not scroll. Write what you see.","pass":"Headline + key benefit + CTA visible without scrolling.","ref":"Audit wireframes & workflows folder → 01-Homepage - mobile.pdf; 02-Product page - mobile.pdf","importance":"Critical"},
  {"id":"MB-002","tab":"Mobile","section":"Mobile – first screen","checkpoint":"On the product page, price and add-to-cart are reachable within one scroll (or a sticky buy bar appears)","why":"An oversized image gallery pushing price and CTA two scrolls down costs sales.","how":"On a phone, count how many scrolls until price and the add-to-cart button appear.","pass":"≤1 scroll, or a sticky bar shows them.","ref":"Optimizers past audit (Balqees mobile PDP)","importance":"High"},
  {"id":"MB-003","tab":"Mobile","section":"Mobile – sticky","checkpoint":"A sticky add-to-cart bar appears on product pages after scrolling past the main button","why":"Keeps the buying action one tap away during long product pages.","how":"Scroll down a product page on a phone.","pass":"Sticky bar with price + add-to-cart appears and works.","ref":"Audit wireframes & workflows folder → 02-Product page - mobile.pdf","importance":"High"},
  {"id":"MB-004","tab":"Mobile","section":"Mobile – navigation","checkpoint":"Hamburger menu opens quickly, shows main categories first, and closes easily","why":"Mobile shoppers navigate mostly through the menu.","how":"Open and close the menu; tap 3 categories.","pass":"Fast, clear, categories first, easy to close.","ref":"","importance":"Medium"},
  {"id":"MB-005","tab":"Mobile","section":"Mobile – tap targets","checkpoint":"All buttons, links, swatches and quantity controls are at least 44×44px and spaced apart","why":"Small or crowded targets cause mis-taps (e.g. deleting instead of adding).","how":"Tap every control in the buy box and cart with your thumb.","pass":"No mis-taps; controls comfortably sized.","ref":"","importance":"High"},
  {"id":"MB-006","tab":"Mobile","section":"Mobile – thumb zone","checkpoint":"Key actions (add to cart, checkout) sit in the lower, easy-to-reach part of the screen","why":"Thumbs reach the bottom of the screen most easily.","how":"Hold the phone in one hand and try to reach each main button.","pass":"Main CTAs reachable one-handed.","ref":"","importance":"Medium"},
  {"id":"MB-007","tab":"Mobile","section":"Mobile – content","checkpoint":"Long sections are collapsed into accordions or tabs, and images are not cropped badly","why":"Endless scrolling hides key content; bad crops hide the product.","how":"Scroll each page; look at image crops and section length.","pass":"Readable, collapsed where long, images framed well.","ref":"","importance":"Medium"},
  {"id":"MB-008","tab":"Mobile","section":"Mobile – forms","checkpoint":"Every form field uses the right keyboard and zoom does not jump when tapping a field (font ≥16px)","why":"iPhone zooms into fields with small text, which disorients users.","how":"Tap into search, newsletter and checkout fields on an iPhone.","pass":"No auto-zoom; right keyboards.","ref":"","importance":"Medium"},
  {"id":"MB-009","tab":"Mobile","section":"Mobile – performance","checkpoint":"Pages feel fast on 4G: content appears in under ~2.5 s and nothing jumps while loading","why":"Slow or jumpy pages lose mobile visitors before they see the offer.","how":"Load each page on a phone with Wi-Fi off. Cross-check with the Stage 2 PageSpeed report.","pass":"Content appears quickly; no layout jumps.","ref":"CRO board → Stage 2 Page Speed Report","importance":"High"},
  {"id":"MB-010","tab":"Mobile","section":"Mobile – in-app browsers","checkpoint":"Key flows work inside the Instagram, TikTok and Facebook in-app browsers (product page → cart → checkout)","why":"Paid social traffic opens inside these browsers; broken flows there waste ad spend.","how":"Send yourself the product link in Instagram DM and TikTok, open it inside the app, and add to cart through to checkout.","pass":"Full flow works with no login or payment errors.","ref":"CRO board → Stage 4 notes (in-app browsers)","importance":"High"},
  {"id":"MB-011","tab":"Mobile","section":"Mobile – orientation","checkpoint":"The site works in landscape and on small phones (360px) without horizontal scrolling","why":"Some visitors use small or rotated screens.","how":"Test at 360px width and in landscape.","pass":"No sideways scrolling or cut-off buttons.","ref":"","importance":"Low"},
  {"id":"TR-001","tab":"Trust & Social Proof","section":"Reviews","checkpoint":"Star rating + review count are shown consistently: homepage product tiles, collection cards, product page (near title) and cart","why":"Consistent, countable social proof at every decision point is one of the strongest conversion levers.","how":"Check one best seller on each page type and note where its rating appears.","pass":"Same rating/count visible everywhere the product appears.","ref":"Optimizers past audits (Tharaa, Balqees)","importance":"High"},
  {"id":"TR-002","tab":"Trust & Social Proof","section":"Reviews","checkpoint":"Reviews are believable: real names, dates, photos, a mix of 4 and 5 stars, and the brand replies to negative ones","why":"Perfect 5.0 scores with no text look fake; replies to criticism build trust.","how":"Read 15 reviews on two products.","pass":"Varied, detailed, dated reviews with photos; replies present.","ref":"","importance":"High"},
  {"id":"TR-003","tab":"Trust & Social Proof","section":"Reviews","checkpoint":"The highest-priced products have the strongest proof (not the weakest)","why":"Loss aversion is highest on expensive items; that is where proof matters most.","how":"Compare review counts on the 3 most expensive vs 3 cheapest products.","pass":"Expensive items have solid review counts and UGC.","ref":"Optimizers past audit (Tharaa bundle)","importance":"Medium"},
  {"id":"TR-004","tab":"Trust & Social Proof","section":"UGC","checkpoint":"Customer photos/videos (UGC) appear on the homepage and product pages","why":"Real customers using the product is more convincing than studio photos.","how":"Look for customer photos/videos, TikTok/Instagram embeds.","pass":"UGC section on homepage and PDP.","ref":"Website Auditing Sheet - Product Page (rows 19, 24)","importance":"Medium"},
  {"id":"TR-005","tab":"Trust & Social Proof","section":"Guarantees","checkpoint":"A risk-reversal (money-back / exchange / satisfaction guarantee) is stated near the add-to-cart button","why":"Guarantees lower the perceived risk of buying from an unknown brand.","how":"Look within one screen of the add-to-cart button.","pass":"Short guarantee line + link to policy beside the CTA.","ref":"","importance":"High"},
  {"id":"TR-006","tab":"Trust & Social Proof","section":"Trust badges","checkpoint":"Payment and security seals sit right next to the add-to-cart and checkout buttons (not only in the footer)","why":"Seals work at the moment of decision, not at the bottom of the page.","how":"Check under/next to add-to-cart and checkout buttons.","pass":"Payment icons and a secure-checkout line anchored to the CTA.","ref":"Website Auditing Sheet - Product Page (row 10: 'Anchor payment seals next to the CTA')","importance":"High"},
  {"id":"TR-007","tab":"Trust & Social Proof","section":"Authority","checkpoint":"Press mentions, certifications, awards, retailer or partner logos are shown (only real ones)","why":"Third-party authority transfers trust to the brand.","how":"Look for 'As seen in', certificates, lab tests, partner logos.","pass":"Real, verifiable authority shown high on the page.","ref":"Website Auditing Sheet - Product Page (row 13)","importance":"Medium"},
  {"id":"TR-008","tab":"Trust & Social Proof","section":"Authority","checkpoint":"Third-party verification badges (if the brand has them) are placed near price/CTA, not buried below reviews","why":"A strong seal far from the CTA does nothing. Found on a past client audit.","how":"Find the seal's position relative to the buy box.","pass":"Seal visible in the first screen of the product page.","ref":"Optimizers past audit (Tharaa transparency seal)","importance":"High"},
  {"id":"TR-009","tab":"Trust & Social Proof","section":"Trust numbers","checkpoint":"A headline social-proof number is shown ('4.8/5 from 10,000 customers', '50,000 orders delivered') and is true","why":"Big, specific numbers create instant credibility.","how":"Look in the hero and near CTAs; ask the client to confirm the number.","pass":"Specific, verified number near the top.","ref":"Website Auditing Sheet - Product Page (row 5)","importance":"Medium"},
  {"id":"TR-010","tab":"Trust & Social Proof","section":"Contact proof","checkpoint":"A real phone number / WhatsApp and physical address (if any) are easy to find","why":"Visible contact details prove there are real people behind the store.","how":"Check header, footer and contact page.","pass":"Real, working contact details.","ref":"","importance":"Medium"},
  {"id":"PO-001","tab":"Pricing, Offers & Urgency","section":"Pricing","checkpoint":"Prices are shown clearly with currency, and any compare-at (old) price and saving are visible","why":"Shoppers judge value instantly; a visible saving increases perceived value.","how":"Look at price on cards and product pages.","pass":"Price, old price (if on sale) and saving amount/percentage shown.","ref":"","importance":"High"},
  {"id":"PO-002","tab":"Pricing, Offers & Urgency","section":"Pricing","checkpoint":"Value is framed (cost per use / per ml, 'X days supply', compared with alternatives)","why":"When price is the main objection, framing the value beats discounting. Price was the #1 objection on a past client.","how":"Look for any value-justification copy near the price.","pass":"A short value line near price.","ref":"Optimizers past audit (Tharaa price objection)","importance":"High"},
  {"id":"PO-003","tab":"Pricing, Offers & Urgency","section":"Pricing","checkpoint":"Bundle and multi-buy savings are quantified ('Save 120 EGP'), not just implied ('2×1')","why":"Unquantified savings don't feel like savings.","how":"Open each bundle product page.","pass":"Exact saving amount shown.","ref":"Optimizers past audit (Tharaa bundle)","importance":"Medium"},
  {"id":"PO-004","tab":"Pricing, Offers & Urgency","section":"Pricing","checkpoint":"Payment plans / BNPL (e.g. valU, Tabby, Tamara, Klarna) are shown near the price or CTA where available","why":"Splitting the price lowers the barrier for higher-priced items.","how":"Look under the price.","pass":"Instalment message near price/CTA.","ref":"Website Auditing Sheet - Product Page (row 3 comment: 'Add payment plans close to the CTA')","importance":"Medium"},
  {"id":"PO-005","tab":"Pricing, Offers & Urgency","section":"Urgency & scarcity","checkpoint":"Any scarcity or urgency (low stock, countdown, limited batch) is REAL and verifiable","why":"Fake timers damage trust and can be illegal; real stock counts work. Reject fake urgency.","how":"Reload the page / come back later: does the timer reset? Ask the client for real stock data.","pass":"Only true urgency is used (real stock levels, real sale end dates).","ref":"Optimizers past audit (Tharaa: fake urgency rejected)","importance":"High"},
  {"id":"PO-006","tab":"Pricing, Offers & Urgency","section":"Urgency & scarcity","checkpoint":"Where real stock or sale-end data exists, it is shown near the price ('Only 6 left', 'Sale ends Friday')","why":"Honest scarcity speeds up decisions.","how":"Compare stock data in the store admin or collection filters with what the product page shows.","pass":"Real stock/sale-end message near price.","ref":"Website Auditing Sheet - Product Page (row 7: 'consider adding a scarcity element')","importance":"Medium"},
  {"id":"PO-007","tab":"Pricing, Offers & Urgency","section":"Offers","checkpoint":"The current offer is consistent across ads, announcement bar, product page, cart and checkout","why":"An offer that disappears between ad and checkout feels like a bait-and-switch.","how":"Follow one active offer from the homepage through to checkout.","pass":"Same offer, same terms, applied automatically or with a clear code.","ref":"","importance":"High"},
  {"id":"PO-008","tab":"Pricing, Offers & Urgency","section":"Offers","checkpoint":"A free-shipping progress bar ('Add 120 EGP more for free shipping') appears in the cart drawer, and ideally on the product page","why":"A visible goal increases order value.","how":"Add a product below the threshold; open the drawer and the product page.","pass":"Progress bar visible and accurate.","ref":"","importance":"Medium"},
  {"id":"PO-009","tab":"Pricing, Offers & Urgency","section":"Upsell & cross-sell","checkpoint":"Relevant cross-sells ('Complete your routine', 'Frequently bought together') appear on the product page and in the cart","why":"Increases average order value when the suggestions genuinely match.","how":"Check suggestions on 3 product pages and in the cart.","pass":"Relevant, one-tap-add suggestions.","ref":"Website Auditing Sheet - Product Page (row 27)","importance":"Medium"},
  {"id":"CP-001","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Attention: the first screen has a value proposition, trust cues, social proof, product imagery and ONE clear CTA","why":"The 5 above-the-fold principles from the framework and the PuraU case (CVR 2% → 7%).","how":"Check the first screen of homepage, a PDP and any landing page.","pass":"All five present on each.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.5); Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.3)","importance":"Critical"},
  {"id":"CP-002","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Transformation: the page shows how easy buying is and the end result (order → delivery → outcome)","why":"Added between Attention and Interest because it removes 'how does this work?' doubt.","how":"Find the steps section.","pass":"3 simple steps a 6-year-old would understand.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.6); Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.4)","importance":"High"},
  {"id":"CP-003","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Interest: benefits come BEFORE features; features explain HOW the benefit is delivered","why":"People buy outcomes; features only justify them.","how":"Compare the order of benefit and feature sections.","pass":"Benefits section first.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.7)","importance":"High"},
  {"id":"CP-004","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Desire: reviews, testimonials, case studies and UGC show the outcome the buyer wants","why":"Desire is created by seeing others get the result.","how":"Read the social proof section.","pass":"All four proof types or at least 3.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.8)","importance":"Medium"},
  {"id":"CP-005","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"FAQ: answers ordering, returns, delivery and product-specific questions before the final CTA","why":"Objections are reasons NOT to buy.","how":"Read the FAQ.","pass":"Covers all four topics.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.9)","importance":"Medium"},
  {"id":"CP-006","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Action: CTA repeated at the bottom with product, rating, price and payment/trust icons","why":"Never let a convinced visitor reach a dead end.","how":"Scroll to the end.","pass":"Full CTA block at the bottom.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.10)","importance":"High"},
  {"id":"CP-007","tab":"Copy & Messaging","section":"Page framework (ATIDFA)","checkpoint":"Long pages also include Compare (us vs. them) and Objections stages (ATIDCOA, from the layouts deck)","why":"Extra stages for pricier or competitive products.","how":"Look for comparison + objections sections.","pass":"Present on PDPs and sales pages.","ref":"Audit wireframes & workflows folder → 02-Page Layouts Presentation.pdf","importance":"Low"},
  {"id":"CP-008","tab":"Copy & Messaging","section":"Headlines & value proposition","checkpoint":"Every key page has ONE clear value proposition that names the outcome, not just the product","why":"'Get healthier and happier in 7 days' beats 'Multivitamin 60 capsules'.","how":"Write down the main promise of each page in one sentence.","pass":"You can do it from the page alone.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.5)","importance":"Critical"},
  {"id":"CP-009","tab":"Copy & Messaging","section":"Headlines & value proposition","checkpoint":"The value proposition says why THIS brand is different (unique mechanism, origin, quality proof, guarantee)","why":"Without a difference, shoppers compare on price.","how":"Ask: could a competitor put the same headline on their site?","pass":"No — it is specific to this brand.","ref":"","importance":"High"},
  {"id":"CP-010","tab":"Copy & Messaging","section":"Headlines & value proposition","checkpoint":"Section headlines are benefit statements ('Sleep deeper from night one'), not labels ('Benefits', 'Features')","why":"Most visitors read only headlines while scrolling.","how":"Read only the headlines of a PDP top to bottom.","pass":"The headlines alone tell the sales story.","ref":"Assets → AIDA Framework by Oliver Kenyon.pdf (p.7)","importance":"Medium"},
  {"id":"CP-011","tab":"Copy & Messaging","section":"Headlines & value proposition","checkpoint":"Copy uses the customer's own words (from reviews, surveys, support chats) for problems and outcomes","why":"Visitors recognise their own language and feel understood.","how":"Compare page wording with 10 real reviews.","pass":"Same phrases appear.","ref":"Objection Map tab","importance":"Medium"},
  {"id":"CP-012","tab":"Copy & Messaging","section":"Body copy","checkpoint":"Copy is skimmable: short paragraphs (≤3 lines on mobile), bullet points, bold key phrases","why":"Nobody reads walls of text on a phone.","how":"Scroll a PDP on a phone.","pass":"No long paragraphs; key words bolded.","ref":"Audit wireframes & workflows folder → Examples → PDP","importance":"Medium"},
  {"id":"CP-013","tab":"Copy & Messaging","section":"Body copy","checkpoint":"Every feature statement ends with the benefit it delivers ('… so you wake up without grogginess')","why":"Features alone don't motivate.","how":"Read the features section.","pass":"Each feature tied to a benefit.","ref":"Audit wireframes & workflows folder → Case Study - PuraU.pdf (p.6)","importance":"Medium"},
  {"id":"CP-014","tab":"Copy & Messaging","section":"Body copy","checkpoint":"Claims are specific and provable (numbers, timeframes, certifications) and legally safe (no medical cure claims)","why":"Vague claims are ignored; illegal claims are a real risk for health/beauty brands.","how":"List 5 claims; check each has proof and is allowed.","pass":"Specific, supported, compliant.","ref":"","importance":"High"},
  {"id":"CP-015","tab":"Copy & Messaging","section":"Body copy","checkpoint":"Spelling, grammar, and translation are correct in every language; no placeholder or template text","why":"Errors look untrustworthy.","how":"Read all copy on key pages (run Arabic through a native speaker).","pass":"No errors.","ref":"Optimizers past audit (Inventel)","importance":"High"},
  {"id":"CP-016","tab":"Copy & Messaging","section":"Body copy","checkpoint":"Tone matches the audience and brand consistently across pages","why":"Mixed tone feels like several different stores.","how":"Compare homepage, PDP and emails.","pass":"Consistent voice.","ref":"","importance":"Low"},
  {"id":"CP-017","tab":"Copy & Messaging","section":"CTAs & microcopy","checkpoint":"CTA labels state the action/outcome ('Get my kit', 'Add to cart – ships today'), and the same label is used for the same action everywhere","why":"Sheet comment: 'Only one consistent CTA'. Mixed labels make people wonder if buttons do different things.","how":"List every CTA label.","pass":"Consistent, specific labels.","ref":"Website Auditing Sheet – Product Page tab (row 21)","importance":"High"},
  {"id":"CP-018","tab":"Copy & Messaging","section":"CTAs & microcopy","checkpoint":"Microcopy under/near CTAs removes the last doubt (delivery time, free returns, secure payment, cancel anytime)","why":"Small reassurance at the click moment.","how":"Read text around each main button.","pass":"Reassurance line present.","ref":"Audit wireframes & workflows folder → 10-Leadgen; 02-Product page","importance":"Medium"},
  {"id":"CP-019","tab":"Copy & Messaging","section":"CTAs & microcopy","checkpoint":"Error and empty-state messages are helpful (what went wrong + how to fix)","why":"Unclear errors end checkouts.","how":"Trigger form errors (bad email, empty field).","pass":"Clear, polite messages next to the field.","ref":"","importance":"Medium"},
  {"id":"CP-020","tab":"Copy & Messaging","section":"Offer & proof copy","checkpoint":"The offer is stated in one sentence (what you get, the saving, until when)","why":"Sheet (Listicle): 'Offer should include a sentence describing the offer'.","how":"Find the main offer.","pass":"One clear sentence.","ref":"Website Auditing Sheet – Listicle tab","importance":"Medium"},
  {"id":"CP-021","tab":"Copy & Messaging","section":"Offer & proof copy","checkpoint":"Social proof copy is quantified ('4.8/5 from 10,000 happy customers') and consistent across pages","why":"Different numbers on different pages look fake.","how":"Compare rating claims site-wide.","pass":"Same, real numbers.","ref":"Website Auditing Sheet – Product Page tab (row 5)","importance":"High"},
  {"id":"CP-022","tab":"Copy & Messaging","section":"Offer & proof copy","checkpoint":"Testimonials show first + last name (or first name + initial), photo, and a specific outcome","why":"Sheet: 'actual social proof with images… first and last names'.","how":"Read testimonials.","pass":"Names, photos, outcomes.","ref":"Website Auditing Sheet – Product Page tab (row 12)","importance":"Medium"},
  {"id":"LP-001","tab":"Landing Pages","section":"Sales page","checkpoint":"The page is more aggressive and sales-oriented than a normal PDP (one product, one offer, no navigation leaks)","why":"Sales pages receive warm ad traffic; every element should push to the one CTA.","how":"Compare with the normal PDP; count exit links.","pass":"Logo-only header; one offer; CTA repeated.","ref":"Website Auditing Sheet – Sales page tab (row 1); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"High"},
  {"id":"LP-002","tab":"Landing Pages","section":"Sales page","checkpoint":"Above the fold: trust bar with seals, social proof rating, value proposition, 3 benefit bullets, simple CTA with payment seals, 3 delivery details, a review, product image on the left","why":"The sheet's above-the-fold formula for sales pages (matches the 05-Sales wireframe buy box).","how":"Tick each element in the first screen.","pass":"All 8 elements present.","ref":"Website Auditing Sheet – Sales page tab (rows 2–9); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Critical"},
  {"id":"LP-003","tab":"Landing Pages","section":"Sales page","checkpoint":"Buy box includes 'Starting from' price + real stock indicator, visible variant buttons, quantity next to CTA","why":"Wireframe buy-box anatomy.","how":"Inspect the buy box.","pass":"All present.","ref":"Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-004","tab":"Landing Pages","section":"Sales page","checkpoint":"'As featured on' / 'As recommended by' trust indicators under the hero","why":"Authority right after the promise.","how":"Scroll below hero.","pass":"Real logos.","ref":"Website Auditing Sheet – Sales page tab (row 10); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-005","tab":"Landing Pages","section":"Sales page","checkpoint":"Transformation: Step 1 checkout → Step 2 delivery → Step 3 beneficial outcome","why":"Shows the simple path to the result.","how":"Find the 3 steps.","pass":"3 steps with icons.","ref":"Website Auditing Sheet – Sales page tab (row 11); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-006","tab":"Landing Pages","section":"Sales page","checkpoint":"Benefit images with text, then feature images with text (zig-zag)","why":"Interest stage.","how":"Check the sections.","pass":"Both sections, benefits first.","ref":"Website Auditing Sheet – Sales page tab (rows 12–13); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-007","tab":"Landing Pages","section":"Sales page","checkpoint":"'What's included' describes every item, especially for bundles","why":"Clarity on what arrives.","how":"Find the section.","pass":"Full list + image.","ref":"Website Auditing Sheet – Sales page tab (row 14); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-008","tab":"Landing Pages","section":"Sales page","checkpoint":"Social proof: testimonials and reviews + UGC-style videos","why":"Desire stage.","how":"Find the proof section.","pass":"Written reviews + video carousel.","ref":"Website Auditing Sheet – Sales page tab (rows 15–16); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"High"},
  {"id":"LP-009","tab":"Landing Pages","section":"Sales page","checkpoint":"CTA with payment and trust seals after the social proof (and after features)","why":"Catch visitors when convinced.","how":"Count CTAs.","pass":"≥4 CTA placements, each with seals.","ref":"Website Auditing Sheet – Sales page tab (row 17); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-010","tab":"Landing Pages","section":"Sales page","checkpoint":"Comparison vs competitor with OUR slot larger and more prominent","why":"Answers 'why not cheaper?'.","how":"Find the comparison.","pass":"Highlighted, larger brand column.","ref":"Website Auditing Sheet – Sales page tab (row 18); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"Medium"},
  {"id":"LP-011","tab":"Landing Pages","section":"Sales page","checkpoint":"FAQ section, then UGC images, then one clear CTA at the end","why":"Final objections, proof and action.","how":"Scroll to the end.","pass":"All three present.","ref":"Website Auditing Sheet – Sales page tab (rows 19–21); Audit wireframes & workflows folder → 05-Sales - desktop.pdf","importance":"High"},
  {"id":"LP-012","tab":"Landing Pages","section":"Listicle","checkpoint":"Top: headline + sub-headline, author photo with first and last name (top left) and a publish date","why":"Editorial look builds trust before selling.","how":"Check the hero.","pass":"All present.","ref":"Website Auditing Sheet – Listicle tab (row 1); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-013","tab":"Landing Pages","section":"Listicle","checkpoint":"Credibility bar ('As recommended by' / 'Featured in') right under the hero (wraps to 2 rows on mobile)","why":"Borrowed authority.","how":"Look below the hero.","pass":"Real logos.","ref":"Website Auditing Sheet – Listicle tab (row 2); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-014","tab":"Landing Pages","section":"Listicle","checkpoint":"Each list item has an image or GIF, a numbered headline, a short paragraph and a list of benefits","why":"Scannable reasons; numbers keep people reading.","how":"Inspect each item.","pass":"All items follow the format; stacked image-first on mobile.","ref":"Website Auditing Sheet – Listicle tab (row 3); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-015","tab":"Landing Pages","section":"Listicle","checkpoint":"Social proof (testimonials) is placed intermittently between items (e.g. after items 3 and 6)","why":"Keeps trust building while reading.","how":"Scroll the list.","pass":"Testimonials spread through the list.","ref":"Website Auditing Sheet – Listicle tab (row 4); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-016","tab":"Landing Pages","section":"Listicle","checkpoint":"A boxed offer after the list gives exclusivity for this page's visitors + real urgency, described in one sentence","why":"The offer converts readers into buyers.","how":"Find the offer box.","pass":"Exclusive offer, one-sentence description, real deadline.","ref":"Website Auditing Sheet – Listicle tab (rows 5–6); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-017","tab":"Landing Pages","section":"Listicle","checkpoint":"Offer box includes star rating, product name, its 3 benefits and a CTA (full width on mobile); a testimonial follows","why":"Completes the decision.","how":"Inspect the offer box.","pass":"All elements.","ref":"Website Auditing Sheet – Listicle tab (row 7); Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-018","tab":"Landing Pages","section":"Listicle","checkpoint":"No CTAs cluttering the list items; header has logo + one CTA (kept on mobile)","why":"Wireframe concentrates conversion in the offer.","how":"Count CTAs.","pass":"Header CTA + offer CTA only.","ref":"Audit wireframes & workflows folder → 06-Listicle - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-019","tab":"Landing Pages","section":"Top-X page","checkpoint":"The page pre-sells the product by comparing it to other products, with a benefit-driven headline","why":"Comparison pages catch people already researching options.","how":"Read the headline and intro.","pass":"Benefit headline; clear comparison purpose.","ref":"Website Auditing Sheet – Top X Page tab (rows 1–2); Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-020","tab":"Landing Pages","section":"Top-X page","checkpoint":"Intro explains the page and who made the list; author photo, first and last name and date","why":"Credibility of the ranking.","how":"Check the hero.","pass":"Author block + explanation.","ref":"Website Auditing Sheet – Top X Page tab (rows 3–4); Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-021","tab":"Landing Pages","section":"Top-X page","checkpoint":"2–3 list items are visible above the fold","why":"The ranking must start immediately.","how":"Open on both devices.","pass":"2–3 items visible without scrolling (desktop).","ref":"Website Auditing Sheet – Top X Page tab (row 5); Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-022","tab":"Landing Pages","section":"Top-X page","checkpoint":"Each item: visible rank number, company logo, benefit-driven USP headline, overall rating/social proof, reviews, price and a CTA","why":"Lets visitors compare at a glance.","how":"Inspect 3 items.","pass":"All elements on every item.","ref":"Website Auditing Sheet – Top X Page tab (rows 6–11); Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-023","tab":"Landing Pages","section":"Top-X page","checkpoint":"Top 3 have a stroke/border and labels ('Highest rated', 'Sells fast'); #1 is the most emphasised","why":"Directs choice to the client's product.","how":"Look at the top 3.","pass":"Bordered + labelled; #1 strongest.","ref":"Website Auditing Sheet – Top X Page tab (row 12); Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-024","tab":"Landing Pages","section":"Top-X page","checkpoint":"After the list: buying guide / methodology content, FAQ, and a closing CTA","why":"Supports undecided readers.","how":"Scroll below the list.","pass":"All three present.","ref":"Audit wireframes & workflows folder → 07-Top X page - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-025","tab":"Landing Pages","section":"Advertorial","checkpoint":"Looks like an article: logo/name top left, links top right (hamburger on mobile), large header image, article title, author name + date + image","why":"Readers trust editorial content more than ads.","how":"Compare with the wireframe.","pass":"Editorial look; no hard-sell hero.","ref":"Website Auditing Sheet – Advertorial Page tab (rows 1–5); Audit wireframes & workflows folder → 08-Advertorial - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-026","tab":"Landing Pages","section":"Advertorial","checkpoint":"The main CTA sits at the very bottom so the page feels informative; any inline 'Sign up now' boxes are soft, with rating + lock line","why":"Sheet says CTA at the bottom; wireframe adds soft inline boxes. Keep it informative first.","how":"Count and place CTAs.","pass":"Final CTA at bottom; inline boxes not aggressive.","ref":"Website Auditing Sheet – Advertorial Page tab (row 6); Audit wireframes & workflows folder → 08-Advertorial - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-027","tab":"Landing Pages","section":"Advertorial","checkpoint":"Images inside the article break up text every 1–2 sections; all images and CTAs link to the offer page","why":"Clicks on images are common — they must go somewhere useful.","how":"Click images and CTAs.","pass":"All go to the offer page.","ref":"Website Auditing Sheet – Advertorial Page tab (rows 7, 11); Audit wireframes & workflows folder → 08-Advertorial - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-028","tab":"Landing Pages","section":"Advertorial","checkpoint":"Social proof with first and last names appears in the body (at least twice)","why":"Real people make the story believable.","how":"Read the body.","pass":"≥2 named testimonials.","ref":"Website Auditing Sheet – Advertorial Page tab (rows 8–9); Audit wireframes & workflows folder → 08-Advertorial - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-029","tab":"Landing Pages","section":"Advertorial","checkpoint":"Real scarcity is used (limited offer/stock/deadline)","why":"Reason to act after reading.","how":"Look near CTAs.","pass":"True scarcity statement.","ref":"Website Auditing Sheet – Advertorial Page tab (row 10)","importance":"Low"},
  {"id":"LP-030","tab":"Landing Pages","section":"Advertorial","checkpoint":"Contextual links inside paragraphs point to the offer","why":"Readers click mid-story.","how":"Check in-text links.","pass":"Several contextual links.","ref":"Website Auditing Sheet – Advertorial Page tab (row 12)","importance":"Medium"},
  {"id":"LP-031","tab":"Landing Pages","section":"Advertorial","checkpoint":"Desktop sidebar contains reviews and a fixed (sticky) CTA; removed on mobile with CTA boxes stacked","why":"Constant access to the offer while reading.","how":"Scroll on desktop.","pass":"Sticky sidebar CTA + reviews.","ref":"Website Auditing Sheet – Advertorial Page tab (row 13); Audit wireframes & workflows folder → 08-Advertorial - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-032","tab":"Landing Pages","section":"Opt-in page","checkpoint":"No scrolling required — the whole opt-in fits in one screen on desktop and mobile","why":"Single-step pages convert best when everything is visible.","how":"Open on both devices.","pass":"No scroll needed.","ref":"Website Auditing Sheet – Opt in pages tab (row 1)","importance":"High"},
  {"id":"LP-033","tab":"Landing Pages","section":"Opt-in page","checkpoint":"Social proof line ('4.8/5 based on 1,000 happy customers') + benefit-driven value prop naming the outcome of opting in","why":"Proof + promise.","how":"Read the top.","pass":"Both present.","ref":"Website Auditing Sheet – Opt in pages tab (rows 2–3)","importance":"High"},
  {"id":"LP-034","tab":"Landing Pages","section":"Opt-in page","checkpoint":"3 benefit-driven bullets, scannable with highlighted words","why":"Fast understanding.","how":"Read the bullets.","pass":"3 bullets with bold key words.","ref":"Website Auditing Sheet – Opt in pages tab (rows 4–5)","importance":"Medium"},
  {"id":"LP-035","tab":"Landing Pages","section":"Opt-in page","checkpoint":"One clear CTA explaining what happens after clicking ('Send me the free guide')","why":"Removes uncertainty.","how":"Read the CTA.","pass":"Specific label.","ref":"Website Auditing Sheet – Opt in pages tab (row 6)","importance":"High"},
  {"id":"LP-036","tab":"Landing Pages","section":"Opt-in page","checkpoint":"Testimonial with image and first + last name","why":"Trust.","how":"Look near the CTA.","pass":"Present.","ref":"Website Auditing Sheet – Opt in pages tab (row 7)","importance":"Medium"},
  {"id":"LP-037","tab":"Landing Pages","section":"Opt-in page","checkpoint":"CTA opens a modal that blurs the background with an email field and a submit CTA; the email actually arrives","why":"Two-step opt-in raises commitment; broken delivery wastes leads.","how":"Click the CTA and submit a test email.","pass":"Modal works; email received.","ref":"Website Auditing Sheet – Opt in pages tab (rows 8–9)","importance":"Critical"},
  {"id":"LP-038","tab":"Landing Pages","section":"VSL page","checkpoint":"Above the fold: benefit-driven headline naming the outcome, with the video directly below it","why":"The video carries the pitch; the headline earns the play.","how":"Open the page.","pass":"Headline + video visible.","ref":"Website Auditing Sheet – VSL (Video Sales Letter) tab (rows 1–2)","importance":"High"},
  {"id":"LP-039","tab":"Landing Pages","section":"VSL page","checkpoint":"Video autoplays muted with captions and a clear 'tap to unmute' prompt; loads fast on mobile","why":"Muted autoplay is allowed by browsers; captions keep silent viewers.","how":"Load on phone and desktop.","pass":"Autoplay muted, captions, quick start.","ref":"Website Auditing Sheet – VSL (Video Sales Letter) tab (row 2)","importance":"High"},
  {"id":"LP-040","tab":"Landing Pages","section":"VSL page","checkpoint":"CTA anchored with trust seals and ratings, naming the next step ('Book my free call')","why":"Clarity at the decision point.","how":"Inspect the CTA.","pass":"Next step named; seals + rating.","ref":"Website Auditing Sheet – VSL (Video Sales Letter) tab (row 3)","importance":"Medium"},
  {"id":"LP-041","tab":"Landing Pages","section":"VSL page","checkpoint":"Sections: Recommended by → Transformation (book call → receive call → outcome) → Benefits → CTA → Features → CTA → About us → Social proof/case studies → FAQ → final CTA","why":"Full sheet structure for VSL pages.","how":"List the sections.","pass":"All present in order; every CTA anchored with proof and trust.","ref":"Website Auditing Sheet – VSL (Video Sales Letter) tab (rows 4–13)","importance":"High"},
  {"id":"LP-042","tab":"Landing Pages","section":"VSL page","checkpoint":"Booking/next step works end-to-end (calendar loads, confirmation email arrives)","why":"A broken booking loses the most expensive leads.","how":"Book a test slot.","pass":"Booking confirmed.","ref":"","importance":"Critical"},
  {"id":"LP-043","tab":"Landing Pages","section":"All landing pages","checkpoint":"The page has ONE goal and every button leads to it (no competing offers, minimal or no navigation)","why":"Landing pages convert best when there is only one thing to do.","how":"List every button and link on the page and where each goes.","pass":"All main buttons go to the same action; header has logo (and at most a header CTA).","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf; Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-044","tab":"Landing Pages","section":"All landing pages","checkpoint":"A star-rating strip ('★★★★★ 4.8/5 from X reviews') sits above the headline AND directly above every repeated CTA","why":"Every wireframe repeats the rating right where the visitor decides.","how":"Scroll the page and note what sits above each button.","pass":"Rating strip above the H1 and above each CTA.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf; Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf; Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-045","tab":"Landing Pages","section":"All landing pages","checkpoint":"The CTA is repeated after every major section (at least 4 times on a long page)","why":"Visitors decide at different points; the button must be there when they do.","how":"Count the CTAs while scrolling.","pass":"CTA after hero, transformation, social proof, FAQ and in the closing band.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf; Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf; Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-046","tab":"Landing Pages","section":"All landing pages","checkpoint":"A security/privacy line (lock icon + short reassurance) sits directly under every form button and CTA","why":"Removes 'will they spam me / is this safe' doubt at the moment of action.","how":"Look under each submit/CTA button.","pass":"Lock icon + line such as 'We never share your details'.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf; Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-047","tab":"Landing Pages","section":"All landing pages","checkpoint":"A guarantee / risk-reversal block exists (none of the wireframes include one, so check the live page specifically)","why":"Risk reversal is one of the strongest conversion levers and is easy to forget.","how":"Search the page for 'guarantee', 'refund', 'free cancellation', 'no obligation'.","pass":"Clear guarantee near the main CTA.","ref":"Gap found across wireframes 09–16","importance":"High"},
  {"id":"LP-048","tab":"Landing Pages","section":"All landing pages","checkpoint":"CTA buttons carry a specific, benefit-led label (not 'Submit' / 'Click here')","why":"The wireframes leave labels blank — the live page must fill them with intent ('Get my free plan').","how":"Read every CTA label.","pass":"Labels describe what the visitor gets.","ref":"Gap found across wireframes 09–16","importance":"High"},
  {"id":"LP-049","tab":"Landing Pages","section":"All landing pages","checkpoint":"On mobile, USP bars and testimonials become swipe carousels with visible arrows, logo rows wrap, and images sit above their text","why":"These are the mobile patterns in every wireframe; they keep the page short and scannable.","how":"View the page at 390px wide.","pass":"Carousels work with swipe and arrows; nothing overflows sideways.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf; Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-050","tab":"Landing Pages","section":"Quiz page","checkpoint":"A value-proposition headline sits above the quiz and the first question is visible without scrolling (desktop and mobile)","why":"The visitor must understand why to take the quiz and see how easy it is.","how":"Open the page on both devices; don't scroll.","pass":"Headline, progress bar, question and options all visible.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-051","tab":"Landing Pages","section":"Quiz page","checkpoint":"A progress indicator shows the total number of steps and the current step, and it moves forward after each answer","why":"Knowing how much is left stops people abandoning halfway.","how":"Answer two questions and watch the indicator.","pass":"e.g. 5 dots, current one filled, advances each step.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-052","tab":"Landing Pages","section":"Quiz page","checkpoint":"A time expectation is shown ('This should take less than 3 minutes')","why":"Short, promised effort increases starts.","how":"Look near the question title.","pass":"Clock icon + time line.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-053","tab":"Landing Pages","section":"Quiz page","checkpoint":"One question per screen, phrased as a question, with about 4 answer choices","why":"Fewer choices per screen = faster answers.","how":"Count questions and options per screen.","pass":"One question, ~4 options.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-054","tab":"Landing Pages","section":"Quiz page","checkpoint":"Answers are large tappable tiles (full width on mobile) with an icon each, and the selected tile is clearly highlighted","why":"Big tiles are easy to tap; icons speed up scanning; the selected state confirms the choice.","how":"Tap answers on a phone.","pass":"Big tiles, icons, obvious selected state.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-055","tab":"Landing Pages","section":"Quiz page","checkpoint":"A full-width, high-contrast continue button sits directly under the options","why":"Clear next step.","how":"Look under the answer tiles.","pass":"Button directly below options, easy to tap.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-056","tab":"Landing Pages","section":"Quiz page","checkpoint":"A testimonial (face, stars, name) sits under the CTA","why":"Reassures people the result is worth it.","how":"Scroll below the CTA.","pass":"Testimonial with photo and rating.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-057","tab":"Landing Pages","section":"Quiz page","checkpoint":"Header is logo-only and the footer is minimal (no links pulling people away)","why":"Distraction-free flow.","how":"Check header/footer links.","pass":"Logo only; minimal footer.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-058","tab":"Landing Pages","section":"Quiz page","checkpoint":"Email / contact capture comes AFTER the questions (before showing the result), never before question 1","why":"Asking for details first kills starts; after investing time, people give details more easily.","how":"Go through the full quiz.","pass":"Questions first, details at the end.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-059","tab":"Landing Pages","section":"Quiz page","checkpoint":"The result page gives a specific recommendation with a direct add-to-cart / next step","why":"The quiz only pays off if the result leads to a purchase.","how":"Complete the quiz.","pass":"Personalised result + product + CTA.","ref":"Audit wireframes & workflows folder → 09-Quiz - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-060","tab":"Landing Pages","section":"Quiz page","checkpoint":"NOTE: the sheet's Quiz tab is currently a copy of the Home Page tab — use the quiz rows above (from the 09-Quiz wireframe) until the sheet is updated","why":"Prevents auditors from applying homepage criteria to a quiz.","how":"—","pass":"—","ref":"Website Auditing Sheet – Quiz Page tab (row all)","importance":"Low"},
  {"id":"LP-061","tab":"Landing Pages","section":"Lead gen page","checkpoint":"The form is above the fold on desktop (right column) and directly after the hero copy on mobile","why":"Visitors should not hunt for the form.","how":"Open on both devices without scrolling (mobile: one scroll max).","pass":"Form visible immediately.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-062","tab":"Landing Pages","section":"Lead gen page","checkpoint":"The form has its own headline and asks for 3 fields or fewer","why":"Every extra field lowers submissions.","how":"Count fields.","pass":"Headline + ≤3 fields.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-063","tab":"Landing Pages","section":"Lead gen page","checkpoint":"A step indicator (1-2-3) is shown even on a short form","why":"Shows the effort is small and structured.","how":"Look at the top of the form card.","pass":"Numbered steps visible.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-064","tab":"Landing Pages","section":"Lead gen page","checkpoint":"Hero = rating strip + benefit-led H1 + short paragraph + 3 check-mark benefits + a testimonial near the form","why":"This is the wireframe hero formula: proof, promise, benefits, social proof.","how":"Compare the hero with the wireframe.","pass":"All five elements present.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-065","tab":"Landing Pages","section":"Lead gen page","checkpoint":"A USP bar with 4 icon promises sits under the header (and is repeated above the footer)","why":"Answers key doubts (returns, support, quality) instantly.","how":"Look under the header and above the footer.","pass":"4 icon USPs present.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-066","tab":"Landing Pages","section":"Lead gen page","checkpoint":"An 'As recommended by' / press-logo bar sits right below the hero (real logos only)","why":"Borrowed authority right after the promise.","how":"Look below the hero.","pass":"Real media/partner logos.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-067","tab":"Landing Pages","section":"Lead gen page","checkpoint":"The page includes: Transformation (3 steps) → What's included → Social proof (3 testimonials) → FAQ (~6 questions) → closing CTA band","why":"This is the wireframe section order (ATIDFA).","how":"List the page's sections in order.","pass":"All sections present, in this order.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-068","tab":"Landing Pages","section":"Lead gen page","checkpoint":"The submit button shows a success message / thank-you page and the lead actually arrives (CRM / email)","why":"A form that 'works' but loses leads is the most expensive bug.","how":"Submit a test lead and check where it lands.","pass":"Clear confirmation + lead received.","ref":"Audit wireframes & workflows folder → 10-Leadgen - desktop/mobile.pdf","importance":"Critical"},
  {"id":"LP-069","tab":"Landing Pages","section":"Lead gen page","checkpoint":"Company logo top left; trust policy bar; social proof + trust + security with a CTA that scrolls to the form","why":"Sheet lead-gen header formula.","how":"Check the top of the page.","pass":"All present; CTA jumps to the form.","ref":"Website Auditing Sheet – Lead gen page tab (row 1–3)","importance":"Medium"},
  {"id":"LP-070","tab":"Landing Pages","section":"Lead gen page","checkpoint":"Form stands out (outlined border/card), has a headline saying exactly what happens, a progress bar, placeholders in fields and a full-width CTA","why":"Sheet form rules.","how":"Inspect the form.","pass":"All five present.","ref":"Website Auditing Sheet – Lead gen page tab (row 10–14)","importance":"High"},
  {"id":"LP-071","tab":"Landing Pages","section":"Lead gen page","checkpoint":"Transformation explains: Step 1 how you fill the form → Step 2 what happens after → Step 3 the outcome","why":"Sets expectations for the lead process.","how":"Find the steps section.","pass":"3 steps covering the lead journey.","ref":"Website Auditing Sheet – Lead gen page tab (row 16)","importance":"Medium"},
  {"id":"LP-072","tab":"Landing Pages","section":"Lead gen page","checkpoint":"Benefits of the service with an image, social proof from people who went through the process, FAQ, and a final CTA that pulls the user back to the form","why":"Remaining sheet criteria for lead gen.","how":"Scroll below the hero.","pass":"All present; final CTA scrolls to the form.","ref":"Website Auditing Sheet – Lead gen page tab (row 18–21)","importance":"Medium"},
  {"id":"LP-073","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"The first step is an easy, low-commitment question (e.g. a Yes/No toggle), not name/email/phone","why":"Starting easy gets people committed before asking for personal details.","how":"Look at step 1.","pass":"Step 1 is a simple question answered in one tap.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-074","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"On mobile the form card comes immediately after the headline, before the body copy","why":"First question visible without scrolling.","how":"Open on a phone.","pass":"Form right under the headline.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-075","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"The step indicator shows the correct total and current step (the desktop wireframe mislabels it '1 2 2 2 2' — make sure the live page doesn't)","why":"Wrong step numbers confuse users about how much is left.","how":"Click through every step.","pass":"Correct numbering 1…N.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-076","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"Contact details are only asked in the later steps","why":"Higher completion.","how":"Go through the full flow.","pass":"Contact fields last.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-077","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"The page stays short and focused: hero + form + logos + 4 benefits + footer, nothing competing with the form","why":"Extra sections pull attention away from completing the form.","how":"Scroll the page.","pass":"No competing sections or links.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-078","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"Back navigation between steps keeps previous answers","why":"Losing answers makes people quit.","how":"Go forward 2 steps, then back.","pass":"Answers kept.","ref":"Audit wireframes & workflows folder → 11-Multistep lead generation - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-079","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"Used to gamify long lead forms: logo top left, trust bar, form on the right, social proof, 3 bullets, testimonial, form headline explaining what happens","why":"Sheet multistep formula (same base as lead gen).","how":"Compare with the lead gen rows.","pass":"All present.","ref":"Website Auditing Sheet – Multi step lead gen page tab (row 1–11)","importance":"Medium"},
  {"id":"LP-080","tab":"Landing Pages","section":"Multistep lead gen","checkpoint":"Starts with the most interesting question; answer buttons are large and full width; progress bar on the form","why":"Sheet: 'Start with the most interesting question', 'Keep the buttons large as well as full width'.","how":"Go through the steps on a phone.","pass":"Engaging first question; big full-width buttons.","ref":"Website Auditing Sheet – Multi step lead gen page tab (row 12–14)","importance":"High"},
  {"id":"LP-081","tab":"Landing Pages","section":"Webinar page","checkpoint":"Logo-only header (no navigation)","why":"Keeps attention on registering.","how":"Check the header.","pass":"Logo only.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-082","tab":"Landing Pages","section":"Webinar page","checkpoint":"Registration form above the fold on desktop, right after the benefit bullets on mobile","why":"Registration is the only goal.","how":"Open on both devices.","pass":"Form visible early.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-083","tab":"Landing Pages","section":"Webinar page","checkpoint":"Form asks only First name, Last name, Email (+ optional 'Your question') with visible labels above each field","why":"Short form; the optional question raises engagement and attendance.","how":"Check the fields and labels.","pass":"≤4 labelled fields.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-084","tab":"Landing Pages","section":"Webinar page","checkpoint":"Event essentials are shown: date, time WITH timezone, duration, and what attendees will learn (agenda)","why":"The wireframe omits these — without them registrations and show-up rates drop.","how":"Look for date/time/agenda near the form.","pass":"All essentials visible above the fold.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf (gap in wireframe)","importance":"Critical"},
  {"id":"LP-085","tab":"Landing Pages","section":"Webinar page","checkpoint":"Host/speaker block with real photo, name and credentials (fix template typos such as 'Abouts Us')","why":"People attend because of who is speaking.","how":"Find the About/host section.","pass":"Real photo + name + credentials, no typos.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-086","tab":"Landing Pages","section":"Webinar page","checkpoint":"Countdown, seats remaining or replay info are shown (only if true)","why":"Real urgency increases registrations.","how":"Look near the form.","pass":"Real countdown/seat info, or replay policy stated.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf (gap in wireframe)","importance":"Low"},
  {"id":"LP-087","tab":"Landing Pages","section":"Webinar page","checkpoint":"After registering: confirmation page with add-to-calendar buttons and a confirmation email","why":"Calendar adds improve attendance.","how":"Register a test attendee.","pass":"Calendar buttons + email received.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-088","tab":"Landing Pages","section":"Webinar page","checkpoint":"Benefits & Features in alternating image/text rows, social proof (3 testimonials), FAQ (~6) — each followed by a register CTA","why":"Wireframe order; repeated CTAs catch people when convinced.","how":"List sections and CTAs.","pass":"All present with CTAs.","ref":"Audit wireframes & workflows folder → 14-Webinar - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-089","tab":"Landing Pages","section":"Webinar page","checkpoint":"Logo top middle; social proof; headline with value proposition; paragraph on what the webinar is and how it helps; 3 benefit bullets; testimonial from a past attendee","why":"Sheet webinar hero formula.","how":"Check the hero.","pass":"All present.","ref":"Website Auditing Sheet – Webinar Page tab (row 1–6)","importance":"Medium"},
  {"id":"LP-090","tab":"Landing Pages","section":"Webinar page","checkpoint":"The form shows a progress bar and states how long it takes ('Takes 30 seconds')","why":"Sheet row 7.","how":"Inspect the form.","pass":"Both present.","ref":"Website Auditing Sheet – Webinar Page tab (row 7)","importance":"Medium"},
  {"id":"LP-091","tab":"Landing Pages","section":"Webinar page","checkpoint":"About Us section includes a photo of the person giving the webinar; social proof from people who got results; FAQ + final CTA","why":"Sheet rows 11–13.","how":"Scroll the page.","pass":"All present.","ref":"Website Auditing Sheet – Webinar Page tab (row 11–13)","importance":"Medium"},
  {"id":"LP-092","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"Hero = rating strip + benefit H1 + 3 bullets + CTA + App Store / Google Play badges + product shown in a device mockup + testimonial","why":"Shows what the product looks like and how to get it immediately.","how":"Compare the hero with the wireframe.","pass":"All elements present.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-093","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"Benefits are presented BEFORE features, in numbered alternating image/text rows","why":"Visitors care what they get before how it works.","how":"Check section order.","pass":"Benefits section comes first.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-094","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"A 3-step 'how it works' (Transformation) section is present","why":"Makes getting started feel easy.","how":"Find the steps section.","pass":"3 clear steps with icons.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-095","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"A comparison table shows the brand column highlighted with a check on every row vs. 1–2 unnamed competitors","why":"Makes the advantage obvious without naming competitors.","how":"Find the comparison section; check it on mobile.","pass":"Highlighted brand column; on mobile 1 competitor at a time with a pager.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-096","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"Store badges are repeated after every CTA","why":"Lets mobile visitors install from anywhere on the page.","how":"Check under each CTA.","pass":"Badges under each CTA.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-097","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"Pricing / plans, free-trial or 'no card needed' wording, integrations and security badges are present (missing from the wireframe)","why":"These answer the main SaaS objections (cost, risk, compatibility, safety).","how":"Search the page for pricing, trial, integrations, security.","pass":"All four addressed.","ref":"Audit wireframes & workflows folder → 15-SaaS - desktop/mobile.pdf (gap in wireframe)","importance":"High"},
  {"id":"LP-098","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"Navigation links top right; star-review social proof; benefit-driven value prop; 3 bullets; CTA (book a demo / sign up); App Store / Play Store seals; named testimonial with stars","why":"Sheet SaaS hero formula.","how":"Check the first screen.","pass":"All present.","ref":"Website Auditing Sheet – Saas Home Page(software as a service) tab (row 1–7)","importance":"High"},
  {"id":"LP-099","tab":"Landing Pages","section":"SaaS / app page","checkpoint":"USP breakdown with image, social proof (rating, full name, image, comment), comparison vs competitors, FAQs and another CTA","why":"Sheet rows 12–16.","how":"Scroll the page.","pass":"All present.","ref":"Website Auditing Sheet – Saas Home Page(software as a service) tab (row 12–16)","importance":"Medium"},
  {"id":"LP-100","tab":"Landing Pages","section":"Service page","checkpoint":"Header shows nav + centred logo + a header CTA on desktop; hamburger + cart/contact icon on mobile","why":"Keeps the main action one click away.","how":"Check headers on both devices.","pass":"Matches description.","ref":"Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Low"},
  {"id":"LP-101","tab":"Landing Pages","section":"Service page","checkpoint":"Hero = rating strip + benefit H1 + 3 bullets + CTA + image + testimonial; press-logo bar below","why":"Wireframe hero formula.","how":"Compare with the wireframe.","pass":"All elements present.","ref":"Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-102","tab":"Landing Pages","section":"Service page","checkpoint":"Benefits shown as a 6-icon grid (3×2 desktop, 2×3 mobile) and features as alternating image/text blocks with check bullets","why":"Scannable value.","how":"Check those sections.","pass":"Grid + feature blocks present.","ref":"Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-103","tab":"Landing Pages","section":"Service page","checkpoint":"A 'Secure checkout' / reassurance line sits above the final CTA, and the footer shows payment badges, social links and a newsletter field","why":"Final reassurance + trust details at the end.","how":"Scroll to the closing band and footer.","pass":"All present.","ref":"Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"Medium"},
  {"id":"LP-104","tab":"Landing Pages","section":"Service page","checkpoint":"Service area, availability / booking slots and response time are stated","why":"Visitors must know you can serve them, when.","how":"Look near the hero and CTA.","pass":"Clear area, availability and response time.","ref":"Audit wireframes & workflows folder → 16-Service - desktop/mobile.pdf","importance":"High"},
  {"id":"LP-105","tab":"Landing Pages","section":"Service page","checkpoint":"Logo top middle; CTA stating the next step; star-rating social proof; benefit value prop; 3 bullets; video or picture on the right","why":"Sheet service hero formula.","how":"Check the first screen.","pass":"All present.","ref":"Website Auditing Sheet – Service tab (row 1–5, 7)","importance":"High"},
  {"id":"LP-106","tab":"Landing Pages","section":"Service page","checkpoint":"A CTA anchored with a success story (image + full name); 'As recommended / trusted by'; transformation steps; benefits; features (image + text); social proof; FAQs; closing benefit headline + proof + trust + CTA","why":"Remaining sheet rows for service pages.","how":"List sections.","pass":"All present.","ref":"Website Auditing Sheet – Service tab (row 6, 8–14)","importance":"Medium"},
];
